/* =========================================================
   Web dashboard views
   ========================================================= */
const NAV=[['dashboard','dashboard'],['households','house'],['centers','building'],['inventory','package'],['distributions','gift'],['verify','shield'],['cards','qr'],['reports','file'],['devices','phone'],['users','users'],['audit','list'],['config','sliders'],['system','flow']];
const NAV_GROUPS=[['Overview',['dashboard']],['Registry',['households','verify','cards']],['Operations',['centers','inventory','distributions','reports']],['Admin',['devices','users','audit','config']],['Help',['system']]];
const NAV_IC=Object.fromEntries(NAV);

function Login(){
 const demo=[['u1','Admin','Sees every barangay, reports and settings'],['u2','Barangay Encoder','Registers families and prints QR cards'],['u3','Barangay Officer','Checks and approves walk-in families'],['u4','Scanner Volunteer','Scans cards at the evacuation center (phone)']];
 return `<div class="login enter"><div class="login-card">
  <div class="brand-lg">${LOGO(52)}<div><div class="wordmark">Kaligtasan<span>ID</span></div><div class="muted sm">Household QR ID for evacuation centers · ${esc(DB.settings.municipality)}, ${esc(DB.settings.province)}</div></div></div>
  <div><h1 class="h1">Log in</h1><p class="lede sm">For barangay and municipal DRRM staff and volunteers.</p></div>
  <form class="stack" onsubmit="A.login(event)">
   <label class="field" for="lg-user"><span>Email or username</span><input id="lg-user" autocomplete="username" required></label>
   <label class="field" for="lg-pass"><span>Password</span><input id="lg-pass" type="password" autocomplete="current-password" required></label>
   <div class="err" id="lg-err" role="alert"></div>
   <button class="btn btn-primary btn-lg" type="submit">Log in</button>
  </form>
  <div><div class="eyebrow">Try it: choose a role · sample data</div><div class="demo-grid">${demo.map(([id,r,s])=>`<button class="demo-btn" onclick="A.demo('${id}')"><b>${r}</b><span>${s}</span></button>`).join('')}</div></div>
  <p class="foot">${icon('lock',13)} Data is protected under the Data Privacy Act of 2012 (RA 10173).</p>
 </div></div>`}

function Shell(){
 const v=S.view,enter=S.prevView!==v;S.prevView=v;
 const navOn=v==='import'||v==='walkin'?'households':v;
 const pend=DB.households.filter(h=>h.status==='pending'&&vis(h)&&brgyOk(h.brgy)).length;
 const items=NAV_GROUPS.map(([g,keys])=>{const ks=keys.filter(can);if(!ks.length)return '';
  return `${g==='Overview'?'':`<div class="nav-group">${g}</div>`}${ks.map(k=>`<a href="#${k}" class="${navOn===k?'on':''}" ${navOn===k?'aria-current="page"':''} onclick="A.nav(false)">${icon(NAV_IC[k],18)}<span>${t(k)}</span>${k==='verify'&&pend?`<span class="cnt">${pend}</span>`:''}</a>`).join('')}`}).join('');
 return `<div class="app ${S.nav?'nav-open':''}">
 <aside class="side" aria-label="Main navigation"><div class="brand">${LOGO(34)}<div><div class="wordmark">Kaligtasan<span>ID</span></div><small>${esc(DB.settings.municipality)}, ${esc(DB.settings.province)} · DRRM</small></div></div>
  <nav class="nav">${items}</nav>
  <div class="side-foot">Sample data for demo only.<br>RA 10173 compliant design.</div></aside>
 <div class="scrim" onclick="A.nav(false)"></div>
 <div class="body">${Top()}<main class="main" id="main"><div class="view ${enter?'enter':''}">${(VIEWS[v]||VIEWS.dashboard)()}</div></main></div></div>
 ${S.drawer?Drawer():''}${S.modal?Modal():''}${S.cmdk?Cmdk():''}`}

function Top(){
 const u=S.user,pend=DB.checkins.filter(x=>x.synced===false).length+DB.dists.filter(x=>x.synced===false).length+DB.households.filter(x=>x.synced===false).length;
 const bsel=u.role==='admin'?`<select class="sel-inline min-w-0 max-w-32 md:max-w-none" aria-label="Barangay" onchange="A.brgy(this.value)"><option value="all">All barangays</option>${DB.brgys.map(b=>`<option value="${b.id}" ${S.brgy===b.id?'selected':''}>Brgy. ${esc(b.name)}</option>`).join('')}</select>`:`<span class="chip">${icon('pin',14)}Brgy. ${esc(brgyOf(u.brgy).name)}</span>`;
 const al=DB.settings.alert!=='0'?`<span class="chip alertlvl hide-sm" title="${esc(DB.settings.alertName)} Alert Level ${esc(DB.settings.alert)} (sample)">${icon('alert',15)}<span class="hidden 2xl:inline">${esc(DB.settings.alertName)} </span><span>Alert ${esc(DB.settings.alert)}</span></span>`:'';
 const sync=`<button class="chip hide-sm" style="cursor:${u.role==='admin'?'pointer':'default'}" onclick="${u.role==='admin'?"location.hash='devices'":''}" title="${pend?`${pend} ${t('pending')}`:t('allsynced')}" aria-label="${pend?`${pend} ${t('pending')}`:t('allsynced')}">${pend?icon('refresh',14):icon('check',14)}<span class="hidden xl:inline">${pend?`${pend} ${t('pending')}`:t('allsynced')}</span>${pend?`<span class="xl:hidden">${pend}</span>`:''}</button>`;
 const al2=alerts(),nBad=al2.filter(a=>a[0]==='bad').length;
 const bell=`<div class="rel"><button class="icon-btn relative" data-tour="bell" aria-label="Notifications (${al2.length})" aria-expanded="${S.menu==='bell'}" onclick="A.menu('bell')">${icon('bell',19)}${al2.length?`<span class="bell-dot" style="${nBad?'':'background:var(--warn);color:#1B1F24'}">${al2.length}</span>`:''}</button>
  ${S.menu==='bell'?`<div class="pop" role="menu"><div class="flex items-center justify-between px-2.5 pt-1.5 pb-2"><b class="text-sm">Needs attention</b><span class="text-xs text-muted">${plural(al2.length,'item')}</span></div>${al2.map(([l,txt,go])=>`<a class="pop-item" ${can(go)?`href="#${go}"`:''} onclick="A.menu(false)"><span class="${l==='bad'?'text-bad-ink':'text-warn-ink'}">${icon('alert',16)}</span><span class="flex-1">${txt}</span>${can(go)?`<span class="text-faint">${icon('right',15)}</span>`:''}</a>`).join('')||`<div class="pop-item text-muted">${icon('check',16)}No capacity, stock or sync warnings right now.</div>`}</div>`:''}</div>`;
 const th=S.theme;
 return `<header class="top"><button class="icon-btn menu-btn" aria-label="Open menu" onclick="A.nav(true)">${icon('menu',20)}</button>${bsel}${al}
 <button class="kbar-btn" data-tour="search" onclick="A.cmdk(true)" aria-label="Search households and pages">${icon('search',16)}<span>Search…</span><span class="kbd">Ctrl K</span></button>
 <div class="grow"></div>
 <button class="icon-btn lg:hidden" data-tour="search" aria-label="Search" onclick="A.cmdk(true)">${icon('search',19)}</button>
 ${sync}${bell}
 <button class="icon-btn" data-tour="help" aria-label="Help: replay the tour" title="Help: replay the tour" onclick="A.tour()">${icon('help',19)}</button>
 <button class="btn btn-accent btn-sm" data-tour="scanner" onclick="A.go('scanner')">${icon('scan',16)}<span class="hide-sm">${t('openScanner')}</span></button>
 <div class="rel"><button class="userbtn" data-tour="account" onclick="A.menu('user')" aria-label="Account menu" aria-expanded="${S.menu==='user'}"><span class="avatar">${initials(u.name)}</span><span class="who"><b>${esc(u.name)}</b><span>${ROLE[u.role].label}</span></span></button>
 ${S.menu==='user'?`<div class="menu" role="menu"><div style="padding:8px 10px 10px"><b>${esc(u.name)}</b><div class="sm muted">${esc(u.email)}</div><div class="sm muted">${ROLE[u.role].label}</div></div>
  <div class="theme-row" role="group" aria-label="Theme">${[['system','auto','Auto'],['light','sun','Light'],['dark','moon','Dark']].map(([k,ic,l])=>`<button class="${th===k?'on':''}" aria-pressed="${th===k}" onclick="A.theme('${k}')">${icon(ic,14)}${l}</button>`).join('')}</div>
  <div class="flex items-center gap-2.5 px-2.5 pt-1.5 text-sm font-medium">Text size</div>${sizeRow()}
  <label class="flex items-center gap-2.5 px-2.5 py-1.5 text-sm font-medium">${icon('globe',16)}<span class="flex-1">Language</span><select class="sel-inline" style="min-height:32px" aria-label="Language" onchange="A.lang(this.value)">${[['en','English'],['fil','Filipino'],['bcl','Bikol']].map(([k,l])=>`<option value="${k}" ${DB.settings.lang===k?'selected':''}>${l}</option>`).join('')}</select></label>
  <button onclick="A.go('scanner')">${icon('phone',16)}${t('openScanner')}</button><button onclick="A.cmdk(true)">${icon('search',16)}Search<span class="kbd">Ctrl K</span></button><button onclick="A.tour()">${icon('help',16)}Take the tour</button><button onclick="A.logout()">${icon('logout',16)}${t('logout')}</button></div>`:''}</div></header>`}

/* ---------- Command palette (Ctrl/Cmd + K) ---------- */
function cmdkResults(){const q=norm(S.cmdk.q);const out=[];
 const pages=NAV.filter(([k])=>can(k)).map(([k,ic])=>({kind:'page',ic,label:t(k),sub:'Page',run:()=>A.go(k)}));
 const thenModal=(v,kind)=>()=>{if(S.view===v)A.modal(kind,{});else{A.go(v);setTimeout(()=>A.modal(kind,{}),60)}};
 const acts=[canEditHH()&&{kind:'act',ic:'userplus',label:t('walkin'),sub:'Action',run:()=>A.startWalkin('web')},canEditHH()&&{kind:'act',ic:'upload',label:'Import records',sub:'Action',run:()=>A.go('import')},{kind:'act',ic:'scan',label:t('openScanner'),sub:'Action',run:()=>A.go('scanner')},can('distributions')&&{kind:'act',ic:'gift',label:'Create distribution round',sub:'Action',run:thenModal('distributions','round')},canStock()&&{kind:'act',ic:'package',label:'Record stock in',sub:'Action',run:()=>{const go=()=>A.modal('stock',{type:'IN'});if(S.view==='inventory')go();else{A.go('inventory');setTimeout(go,60)}}}].filter(Boolean);
 const match=x=>!q||norm(x.label).includes(q);
 out.push(...pages.filter(match),...acts.filter(match));
 if(q.length>=2&&can('households')){const hs=[];for(const h of DB.households){if(!liveHH(h)||!brgyOk(h.brgy))continue;if(hhSearchText(h).includes(q)){hs.push(h);if(hs.length>=8)break}}
  out.push(...hs.map(h=>({kind:'hh',ic:'house',label:headOf(h).name,sub:h.code,run:()=>A.openHH(h.id)})))}
 return out}
function cmdkList(){const r=cmdkResults();if(S.cmdk.i>=r.length)S.cmdk.i=Math.max(0,r.length-1);let last='';
 return r.map((x,i)=>{const sec=x.kind==='hh'?'Households':x.kind==='act'?'Actions':'Pages';const head=sec!==last?`<div class="cmdk-sec">${sec}</div>`:'';last=sec;
  return `${head}<button class="cmdk-item ${i===S.cmdk.i?'on':''}" data-i="${i}" onmousemove="A.cmdkHover(${i})" onclick="A.cmdkRun(${i})">${icon(x.ic,17)}<span class="grow">${esc(x.label)}${x.kind==='hh'?`<span class="sub mono">${esc(x.sub)}</span>`:''}</span>${i===S.cmdk.i?`<span class="text-faint">${icon('enter',15)}</span>`:''}</button>`}).join('')||`<div class="empty">No results. Try a name, household ID or page.</div>`}
function Cmdk(){return `<div class="overlay" style="z-index:59" onclick="A.cmdk(false)"></div><div class="cmdk" onclick="if(event.target===this)A.cmdk(false)"><div class="cmdk-box" role="dialog" aria-modal="true" aria-label="Search">
 <div class="cmdk-in">${icon('search',18)}<input id="cmdk-q" value="${esc(S.cmdk.q)}" placeholder="Search households by name or ID, or jump to a page" autocomplete="off" oninput="A.cmdkQ(this.value)" onkeydown="A.cmdkKey(event)" aria-label="Search"><span class="kbd">Esc</span></div>
 <div class="cmdk-list" id="cmdk-list">${cmdkList()}</div>
 <div class="cmdk-foot"><span>↑ ↓ to move</span><span>Enter to open</span><span>Esc to close</span></div></div></div>`}

/* ---------- Dashboard ---------- */
function hhVisible(){return DB.households.filter(h=>liveHH(h)&&brgyOk(h.brgy))}
function centersV(){return DB.centers.filter(c=>brgyOk(c.brgy))}
function alerts(){const a=[];
 centersV().forEach(c=>{if(c.status==='Closed')return;const o=occ(c.id);if(o>c.capacity)a.push(['bad',`${esc(c.name)} is over capacity: ${o} of ${c.capacity} people.`,'centers']);else if(o>=c.capacity*.9)a.push(['warn',`${esc(c.name)} is almost full: ${o} of ${c.capacity} people.`,'centers'])});
 lowItems().forEach(i=>a.push(['warn',`${esc(i.name)} is low: ${fmtN(i.stock)} ${i.unit}${i.stock===1?'':'s'} left, reorder level is ${fmtN(i.reorder)}.`,'inventory']));
 const conf=DB.syncErrors.filter(e=>!e.resolved&&e.kind==='conflict').length;if(conf)a.push(['bad',`${plural(conf,'possible double claim')} found during sync. Review it.`,'devices']);
 return a}
const VIEWS={};
VIEWS.dashboard=function(){
 const hs=hhVisible(),reg=hs.filter(h=>h.status!=='inactive');
 const ver=reg.filter(h=>h.status==='verified').length,imp=reg.filter(h=>h.status==='imported').length,pen=reg.filter(h=>h.status==='pending').length;
 const cs=centersV(),act=cs.flatMap(c=>activeAt(c.id)),evH=act.map(c=>hh(c.hh)).filter(Boolean);
 const people=evH.reduce((s,h)=>s+h.members.length,0),ms=evH.flatMap(h=>h.members),vul=ms.filter(m=>m.needs.length).length,nc=needCounts(ms);
 const al=alerts();
 const now=Date.now();let vals=[],labels=[],every=6,unit='check-ins';
 const csIds=new Set(cs.map(c=>c.id));const cin=DB.checkins.filter(c=>csIds.has(c.center)&&vis(c));
 if(S.range==='24h'){for(let i=23;i>=0;i--){const e=now-i*H,s=e-H;vals.push(cin.filter(c=>c.inAt>=s&&c.inAt<e).length);const d=new Date(s);labels.push(i===0?'Now':`${(d.getHours()%12)||12}${d.getHours()<12?'a':'p'}`)}}
 else{every=1;for(let i=6;i>=0;i--){const d0=new Date(now-i*D);d0.setHours(0,0,0,0);const s=d0.getTime(),e=s+D;vals.push(cin.filter(c=>c.inAt>=s&&c.inAt<e).length);labels.push(i===0?'Today':`${d0.getDate()} ${MON[d0.getMonth()]}`)}}
 const open=DB.rounds.filter(r=>r.status==='Open'&&csIds.has(r.center));
 const devs=DB.devices.filter(d=>d.status!=='Revoked'),onl=devs.filter(d=>d.status==='Online').length,wp=devs.filter(d=>pendingOf(d.id)>0).length;
 const low=lowItems().length;
 const opsTabs=[['centers','Centers',cs.filter(c=>c.status!=='Closed').length],['stock','Relief stock',low||null],['rounds','Distribution',open.length]];
 const tk=tabKey('dash',opsTabs);let panel='';
 if(tk==='centers')panel=cs.map(c=>{const o=occ(c.id);return `<button class="occ text-left w-full cursor-pointer rounded-lg -mx-2 px-2 py-1.5 hover:bg-sunk" onclick="A.drawer('center','${c.id}')"><div class="split"><span><b>${esc(c.name)}</b> ${c.status==='Closed'?'<span class="badge b-dark">Closed</span>':''}</span><span class="num sm"><b>${o}</b> / ${c.capacity}</span></div>${occBar(o,c.capacity)}</button>`}).join('')||'<div class="empty">No centers in this barangay.</div>';
 if(tk==='stock')panel=`<div class="list">${DB.items.map(i=>{const lw=i.stock<i.reorder;return `<div class="list-item"><span class="dot ${lw?'warn':'ok'}"></span><div class="grow"><b>${esc(i.name)}</b><div class="bar" style="margin-top:6px;height:6px"><i class="${lw?'warn':'navy'}" style="width:${Math.min(100,i.stock/(Math.max(1,i.reorder)*4)*100).toFixed(1)}%"></i></div></div><span class="num" style="min-width:92px;text-align:right"><b>${fmtN(i.stock)}</b> <span class="muted sm">${esc(i.unit)}${i.stock===1?'':'s'}</span></span>${lw?'<span class="badge b-pending">Low</span>':''}</div>`}).join('')}</div>${can('inventory')?'<a class="sm" href="#inventory">Open inventory</a>':''}`;
 if(tk==='rounds')panel=`${open.map(r=>{const tg=roundTarget(r).size,sv=roundDists(r.id).length;return `<button class="occ text-left w-full cursor-pointer rounded-lg -mx-2 px-2 py-1.5 hover:bg-sunk" onclick="A.drawer('round','${r.id}')"><div class="split"><span><b>${esc(itemOf(r.item).name)}</b> <span class="muted sm">· ${esc(centerOf(r.center).name)} · ${r.code}</span></span><span class="num sm"><b>${sv}</b> of ${tg}</span></div><div class="bar"><i class="navy" style="width:${tg?(sv/tg*100).toFixed(1):0}%"></i></div></button>`}).join('')||'<div class="empty">No open distribution rounds.</div>'}
  <div class="list-item" style="border-top:1px solid var(--line);padding-top:14px">${icon('phone',18)}<div class="grow"><b>Device sync</b><div class="sm muted">${onl} devices online, ${wp} with pending records</div></div>${can('devices')?'<a class="sm" href="#devices">Devices</a>':''}</div>`;
 const bad=al.filter(a=>a[0]==='bad').length;
 return `<div class="page-head"><div><div class="eyebrow">${S.brgy==='all'?`Municipality of ${esc(DB.settings.municipality)}`:`Barangay ${esc(brgyOf(S.brgy).name)}`} · updated ${fmtTime(now)}</div><h1 class="h1">${t('dashboard')}</h1><p class="lede">Who is registered, who is in the evacuation centers, and what needs attention today.</p></div></div>
 ${al.length?`<div class="attn"><span class="${bad?'text-bad-ink':'text-warn-ink'}">${icon('alert',18)}</span><span class="flex-1"><b>${plural(al.length,'item')} need${al.length===1?'s':''} attention</b> <span class="muted hide-sm">· ${al[0][1].replace(/.$/,'')}${al.length>1?` · and ${al.length-1} more`:''}</span></span><button class="btn btn-sm" onclick="event.stopPropagation();A.menu('bell')">Review</button></div>`:`<div class="alert ok">${icon('check',17)}No capacity, stock or sync warnings right now.</div>`}
 <div class="stats">
  <a class="stat" href="#households"><div class="stat-label">Registered households</div><div class="stat-num">${fmtN(reg.length)}</div><div class="stat-sub"><span>${fmtN(ver)} verified</span>·<span>${fmtN(imp)} imported</span></div></a>
  <a class="stat" href="#centers"><div class="stat-label">Currently evacuated</div><div class="stat-num">${fmtN(people)}<small>people</small></div><div class="stat-sub">${plural(evH.length,'household')} in ${plural(cs.filter(c=>c.status!=='Closed').length,'open center')}</div></a>
  <${can('reports')?`a href="#reports" onclick="S.rep='vulnerable'"`:'div'} class="stat"><div class="stat-label">Vulnerable evacuees</div><div class="stat-num">${fmtN(vul)}</div><div class="stat-sub">PWD ${nc.PWD} · Senior ${nc.SENIOR} · Pregnant ${nc.PREGNANT} · Infant ${nc.INFANT}</div></${can('reports')?'a':'div'}>
  <${can('verify')?'a href="#verify"':'div'} class="stat ${pen?'warn':''}"><div class="stat-label">Pending walk-in verifications</div><div class="stat-num">${pen}</div><div class="stat-sub">${pen?'Walk-ins already have temporary access':'Queue is clear'}</div></${can('verify')?'a':'div'}>
 </div>
 <div class="grid2">
  <section class="card stack" style="gap:12px">${tabs('dash',opsTabs,'Operations')}<div class="tab-panel" style="gap:4px">${panel}</div></section>
  <section class="card"><div class="card-head"><div><h2 class="h2">Check-ins</h2><div class="sm muted">${S.range==='24h'?'Per hour':'Per day'} · ${fmtN(vals.reduce((a,b)=>a+b,0))} total</div></div><div class="seg" role="group" aria-label="Date range"><button class="${S.range==='24h'?'on':''}" aria-pressed="${S.range==='24h'}" onclick="A.range('24h')">24 hours</button><button class="${S.range==='7d'?'on':''}" aria-pressed="${S.range==='7d'}" onclick="A.range('7d')">7 days</button></div></div>${barChart(vals,labels,every,unit)}<div class="legend" style="margin-top:8px"><span><i style="background:var(--navy)"></i>Earlier</span><span><i style="background:var(--accent)"></i>${S.range==='24h'?'This hour':'Today'}</span></div></section>
 </div>`};

/* ---------- Households ---------- */
/* Normalized search text per household, cached. Call SEARCH.delete(h) after editing a household. */
const SEARCH=new WeakMap();
function hhSearchText(h){let s=SEARCH.get(h);if(s===undefined){s=norm([h.code,h.location,...h.members.map(m=>m.name)].join(' '));SEARCH.set(h,s)}return s}
function hhList(){const f=S.hf,q=norm(f.q),qd=q.replace(/\D/g,'');
 return DB.households.filter(h=>vis(h)&&brgyOk(h.brgy)&&(f.status==='all'?!['archived','merged'].includes(h.status):h.status===f.status)&&(f.need==='all'||h.members.some(m=>m.needs.includes(f.need)))&&(f.purok==='all'||String(h.purok)===f.purok)&&(!q||hhSearchText(h).includes(q)||(qd.length>=4&&(h.phone||'').replace(/\D/g,'').includes(qd))))}
const hfActive=()=>S.hf.q||S.hf.status!=='all'||S.hf.need!=='all'||S.hf.purok!=='all';
function hhResults(){const list=hhList(),size=25,pages=Math.max(1,Math.ceil(list.length/size));if(S.hf.page>=pages)S.hf.page=pages-1;const rows=list.slice(S.hf.page*size,(S.hf.page+1)*size);
 const sel=S.sel.size;
 return `${sel?`<div class="alert info">${icon('check',16)}<span>${plural(sel,'household')} selected</span><a href="#cards" onclick="S.cardScope='selected'">Print selected cards</a><a href="#" onclick="event.preventDefault();A.clearSel()">Clear</a></div>`:''}
 <div class="tbl-wrap"><table><thead><tr><th style="width:40px"><input type="checkbox" aria-label="Select all on this page" onchange="A.selPage(this.checked)" ${rows.length&&rows.every(h=>S.sel.has(h.id))?'checked':''}></th><th>Household ID</th><th>Head of family</th><th class="r">Members</th><th class="hide-sm">Purok / location</th><th>Special needs</th><th>Status</th><th class="hide-sm">Card</th></tr></thead><tbody>
 ${rows.map(h=>`<tr class="click" onclick="A.openHH('${h.id}')"><td onclick="event.stopPropagation()"><input type="checkbox" aria-label="Select ${h.code}" ${S.sel.has(h.id)?'checked':''} onchange="A.sel('${h.id}',this.checked)"></td><td class="mono">${h.code}</td><td><b>${esc(headOf(h).name)}</b></td><td class="r num">${h.members.length}</td><td class="hide-sm">${h.purok?'Purok '+h.purok:`<span class="sm">${esc(h.location)}</span>`}</td><td>${hhTags(h)}</td><td>${badge(h.status)}</td><td class="hide-sm">${cardBadge(h)}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">No households match these filters. Try clearing the search.</td></tr>'}
 </tbody></table></div>${pager(list.length,S.hf.page,size,'A.hhPage')}`}
VIEWS.households=function(){const f=S.hf,ed=canEditHH();const maxP=Math.max(...DB.brgys.filter(b=>brgyOk(b.id)).map(b=>b.puroks));
 return `<div class="page-head"><div><div class="eyebrow">Registry</div><h1 class="h1">${t('households')}</h1><p class="lede">Imported barangay records and walk-ins. The QR card holds only a random ID; names stay here.</p></div>
 ${ed?`<div class="actions"><a class="btn" href="#import">${icon('upload',16)}Import records</a><a class="btn" href="#cards">${icon('printer',16)}Print cards</a><button class="btn btn-primary" onclick="A.startWalkin('web')">${icon('userplus',16)}${t('walkin')}</button></div>`:''}</div>
 <div class="filters"><div class="search">${icon('search',17)}<input type="search" id="hh-q" placeholder="Search name, household ID, location or phone" value="${esc(f.q)}" oninput="A.hhQ(this.value)" aria-label="Search households"></div>
  <select class="sel-inline" aria-label="Status" onchange="A.hhF('status',this.value)">${[['all','All statuses'],['verified','Verified'],['imported','Imported'],['pending','Walk-in (pending)'],['inactive','Inactive'],['archived','Archived']].map(([k,l])=>`<option value="${k}" ${f.status===k?'selected':''}>${l}</option>`).join('')}</select>
  <select class="sel-inline" aria-label="Special needs" onchange="A.hhF('need',this.value)"><option value="all">Any special needs</option>${Object.keys(NEEDS).map(k=>`<option value="${k}" ${f.need===k?'selected':''}>${NEEDS[k][0]}</option>`).join('')}</select>
  <select class="sel-inline" aria-label="Purok" onchange="A.hhF('purok',this.value)"><option value="all">All puroks</option>${Array.from({length:maxP},(_,i)=>`<option value="${i+1}" ${f.purok===String(i+1)?'selected':''}>Purok ${i+1}</option>`).join('')}</select>${hfActive()?`<button class="btn btn-ghost btn-sm" onclick="A.hhClear()">${icon('x',15)}Clear filters</button>`:''}</div>
 <div id="hh-results">${hhResults()}</div>`};

function HHDrawer(h){const c=cardOf(h),ed=canEditHH(),ci=activeCheckin(h.id),b=brgyOf(h.brgy);
 const acts=ed?[h.status==='pending'?`<button class="btn btn-ok btn-sm" onclick="A.verify('${h.id}')">${icon('check',15)}Verify</button>`:'',h.status==='imported'?`<button class="btn btn-ok btn-sm" onclick="A.verify('${h.id}')">${icon('check',15)}Mark verified</button>`:'',
  `<button class="btn btn-sm" onclick="A.modal('edit-hh',{id:'${h.id}'})">${icon('edit',15)}Edit</button>`,
  `<button class="btn btn-sm" onclick="A.modal('reissue',{id:'${h.id}'})">${icon('card',15)}Reissue card</button>`,
  c&&c.status==='Active'?`<button class="btn btn-sm" onclick="A.modal('deactivate',{id:'${h.id}'})">${icon('ban',15)}Deactivate card</button>`:'',
  !['archived','merged'].includes(h.status)?`<button class="btn btn-sm btn-danger" onclick="A.modal('archive',{id:'${h.id}'})">${icon('archive',15)}Archive</button>`:''].join(''):`<span class="muted sm">${icon('lock',14)} View only for your role</span>`;
 const hist=[...DB.checkins.filter(x=>x.hh===h.id&&vis(x)).flatMap(x=>[{at:x.inAt,txt:`Checked in at ${esc(centerOf(x.center).name)}`,dev:x.device},...(x.outAt?[{at:x.outAt,txt:`Checked out of ${esc(centerOf(x.center).name)}`,dev:x.device}]:[])]),
  ...DB.dists.filter(d=>d.hh===h.id&&vis(d)).map(d=>{const r=roundOf(d.round);return {at:d.at,txt:`Received ${r.qty} × ${esc(itemOf(r.item).name)} (${r.code})${d.state==='conflict'?' · flagged as possible double claim':''}`,dev:d.device}}),
  {at:h.createdAt,txt:h.source==='walkin'?'Registered as walk-in':'Imported from barangay records',dev:h.device}].sort((a,b)=>b.at-a.at);
 const cards=DB.cards.filter(x=>x.hh===h.id).sort((a,b)=>b.issuedAt-a.issuedAt);
 const tb=[['overview','Overview'],['members','Members',h.members.length],['card','Card',cards.length],['activity','Activity',hist.length]];const tk=tabKey('hh',tb);let panel='';
 if(tk==='overview')panel=`<div class="actions">${acts}</div>
  ${h.infoRequested?`<div class="alert warn">${icon('info',16)}<span>More info requested: ${esc(h.infoRequested)}</span></div>`:''}
  <div class="mini-stats"><div><span>Members</span><b>${h.members.length}</b></div><div><span>With special needs</span><b>${h.members.filter(m=>m.needs.length).length}</b></div><div><span>Relief received</span><b>${DB.dists.filter(d=>d.hh===h.id&&vis(d)&&d.state!=='conflict').length}</b></div></div>
  <section class="card"><div class="card-head" style="margin-bottom:10px"><h2 class="h2">Head of family</h2>${hhTags(h)}</div><div class="row"><span class="avatar" style="width:40px;height:40px">${initials(headOf(h).name)}</span><div><b>${esc(headOf(h).name)}</b><div class="sm muted">${ageLabel(headOf(h).birth)||'Age not given'} · ${plural(h.members.length-1,'other member')}</div></div><button class="btn btn-sm" style="margin-left:auto" onclick="A.tab('hh','members')">See members</button></div></section>
  <section class="card"><h2 class="h2" style="margin-bottom:12px">Details</h2><dl class="kv">
  <dt>Barangay</dt><dd>${esc(b.name)}${h.purok?`, Purok ${h.purok}`:''}</dd>
  <dt>Address / location</dt><dd>${esc(h.location)}</dd>
  <dt>Phone</dt><dd>${h.phone?esc(h.phone):'<span class="faint">None</span>'}</dd>
  <dt>Source</dt><dd>${h.source==='walkin'?`Walk-in, registered by ${esc(h.createdBy)} on ${esc(h.device)}`:'Imported barangay record'}</dd>
  <dt>Consent</dt><dd>${h.consentAt?`Signed ${fmtDate(h.consentAt)} · recorded by ${esc(h.consentBy)}`:'<span class="badge b-pending">Not yet collected</span>'}</dd></dl></section>`;
 if(tk==='members')panel=`<div class="tbl-wrap"><table><thead><tr><th>Name</th><th class="hide-sm">Age group</th><th class="hide-sm">Sex</th><th>Relationship</th><th>Special needs</th></tr></thead><tbody>
  ${h.members.map(m=>`<tr><td><b>${esc(m.name)}</b>${m.head?' <span class="badge b-info" style="font-size:11px">Head</span>':''}<span class="sub">${m.birth?`Born ${fmtDate(new Date(m.birth+'T00:00:00'))} · ${ageLabel(m.birth)}`:'Birthdate not given'}</span></td><td class="hide-sm">${ageGroup(m.birth)}</td><td class="hide-sm">${m.sex==='F'?'Female':m.sex==='M'?'Male':'—'}</td><td>${esc(m.rel)}</td><td>${m.needs.length?`<span class="tags">${m.needs.map(n=>tag(n)).join('')}</span>`:'<span class="faint">None</span>'}${m.note?`<span class="sub">${seesMedical()?esc(m.note):icon('lock',12)+' Medical details restricted'}</span>`:''}</td></tr>`).join('')}
  </tbody></table></div>${ed?`<div><button class="btn btn-sm" onclick="A.modal('edit-hh',{id:'${h.id}'})">${icon('edit',15)}Edit members</button></div>`:''}`;
 if(tk==='card')panel=`<section class="card"><div class="card-head"><h2 class="h2">Current card</h2>${c?`<span class="sm muted">Issued ${fmtDate(c.issuedAt)}${c.digital?' · temporary digital QR':''}</span>`:''}</div>
  ${c?`<div class="pair">${cardFront(h,c)}${cardBack(h,c)}</div>${ed?`<div class="actions" style="margin-top:14px"><button class="btn btn-sm" onclick="A.printCards(['${h.id}'])">${icon('printer',15)}Print this card</button></div>`:''}`:'<div class="empty">No active card. Reissue to give this household a new card.</div>'}</section>
  <section class="card"><h2 class="h2" style="margin-bottom:6px">Card history</h2><div class="list">${cards.map(x=>`<div class="list-item sm"><span class="dot ${x.status==='Active'?'ok':x.status==='Lost'?'bad':''}"></span><div class="grow">Card ending <span class="mono">…${x.token.slice(-4)}</span> · issued ${fmtDate(x.issuedAt)}</div><span class="badge ${CARDST[x.status]}">${x.status}</span></div>`).join('')||'<div class="empty">No cards issued.</div>'}</div></section>`;
 if(tk==='activity')panel=`<section class="card"><div class="list">${hist.slice(0,40).map(e=>`<div class="list-item sm"><span class="muted num" style="min-width:150px">${fmtDT(e.at)}</span><div class="grow">${e.txt}</div><span class="mono faint">${esc(e.dev||'')}</span></div>`).join('')}</div>${hist.length>40?`<div class="pager"><span>Showing the latest 40 of ${hist.length}.</span></div>`:''}</section>`;
 return `<div class="drawer-head" style="flex-direction:column;gap:14px;padding-bottom:0"><div class="row" style="width:100%;flex-wrap:nowrap;align-items:flex-start"><div style="flex:1;min-width:0"><div class="eyebrow">Household · ${esc(headOf(h).name)}</div><div class="h1 mono" style="font-family:var(--mono);font-size:22px">${h.code}</div><div class="row" style="margin-top:8px;gap:6px">${badge(h.status)}${cardBadge(h)}${ci?`<span class="badge b-info">In ${esc(centerOf(ci.center).name)}</span>`:''}</div></div><button class="icon-btn" aria-label="Close" onclick="A.close()">${icon('x',20)}</button></div>
  <div style="width:100%">${tabs('hh',tb,'Household sections')}</div></div>
 <div class="drawer-body"><div class="tab-panel">${panel}</div></div>`}

/* ---------- Import ---------- */
const IFIELDS=[['ref','Household no.',true,/house|hh|family no|household/i],['name','Full name',true,/name/i],['birth','Birthdate',true,/birth|dob|bday/i],['sex','Sex',false,/sex|gender/i],['rel','Relationship to head',false,/rel/i],['purok','Purok',false,/purok|zone|sitio/i],['address','Address',false,/addr/i],['phone','Phone',false,/phone|contact|mobile|cell/i],['needs','Special needs',false,/need|pwd|vuln|tag/i]];
function sampleCSV(){const m=DB.households.find(h=>h.code===DB.demo.found);const mb=headOf(m).birth;
 return `household_no,full_name,birthdate,sex,relationship,purok,address,contact_no,special_needs
SR-2026-101,Rogelio Bitarra,1968-04-12,M,Head,5,"Purok 5, San Roque",09171230001,
SR-2026-101,Imelda Bitarra,1971-09-30,F,Spouse,5,,,Medical
SR-2026-101,Lance Bitarra,2013-02-14,M,Son,5,,,
SR-2026-102,Evelyn Cabrera,1949-11-02,F,Head,6,"Purok 6, San Roque",,PWD
SR-2026-102,Kyla Cabrera,2025-06-20,F,Granddaughter,6,,,
SR-2026-103,Maria Santos,${mb},F,Head,3,"Purok 3, San Roque",,
SR-2026-104,Nestor Garcia,,M,Head,2,"Purok 2, San Roque",,
SR-2026-104,Alyssa Garcia,2016-08-09,F,Daughter,2,,,
SR-2026-105,Renato Marbella,1985-01-25,M,Head,7,"Purok 7, San Roque",09981230005,
SR-2026-105,Joy Marbella,1990-03-03,F,Spouse,7,,,Pregnant
SR-2026-105,Gab Marbella,2019-12-12,M,Son,7,,,
,Trisha Atun,2010-05-05,F,Daughter,4,,,`}
function parseCSV(txt){const rows=[];let row=[],f='',q=false;for(let i=0;i<txt.length;i++){const ch=txt[i];if(q){if(ch==='"'){if(txt[i+1]==='"'){f+='"';i++}else q=false}else f+=ch}else if(ch==='"')q=true;else if(ch===','){row.push(f);f=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&txt[i+1]==='\n')i++;row.push(f);f='';if(row.some(x=>x.trim()))rows.push(row);row=[]}else f+=ch}row.push(f);if(row.some(x=>x.trim()))rows.push(row);return rows}
function parseDate(s){s=String(s||'').trim();if(!s)return null;let m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);if(m)return `${m[1]}-${pad(m[2],2)}-${pad(m[3],2)}`;m=s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);if(m)return `${m[3]}-${pad(m[1],2)}-${pad(m[2],2)}`;return 'bad'}
function parseNeeds(s){const o=[];const x=String(s||'').toLowerCase();if(/pwd|disab/.test(x))o.push('PWD');if(/senior/.test(x))o.push('SENIOR');if(/preg/.test(x))o.push('PREGNANT');if(/infant|baby/.test(x))o.push('INFANT');if(/med|sick|ill/.test(x))o.push('MEDICAL');return o}
function memberIndex(){const m=new Map();DB.households.forEach(h=>{if(['archived','merged'].includes(h.status))return;h.members.forEach(x=>{if(x.birth)m.set(norm(x.name)+'|'+x.birth,h)})});return m}
function importAnalyze(){const I=S.imp,idx=memberIndex(),seen=new Set();const col=k=>I.map[k];
 I.analyzed=I.rows.map((r,i)=>{const g=k=>col(k)!==''&&col(k)!=null?String(r[col(k)]??'').trim():'';const o={i,ref:g('ref'),name:g('name'),birthRaw:g('birth'),birth:parseDate(g('birth')),sex:(g('sex')[0]||'').toUpperCase(),rel:g('rel')||'Member',purok:g('purok'),address:g('address'),phone:g('phone'),needs:parseNeeds(g('needs')),errs:[],dup:null};
  if(!o.ref)o.errs.push('Missing household no.');if(!o.name)o.errs.push('Missing name');if(!o.birth)o.errs.push('Missing birthdate');else if(o.birth==='bad')o.errs.push('Birthdate format not recognized');
  if(!o.errs.length){const k=norm(o.name)+'|'+o.birth;if(idx.has(k))o.dup=idx.get(k);if(seen.has(k))o.errs.push('Repeated in this file');seen.add(k)}return o});
 const groups={};I.analyzed.forEach(o=>{if(!o.ref)return;(groups[o.ref]=groups[o.ref]||[]).push(o)});I.groups=groups}
VIEWS.import=function(){const I=S.imp||(S.imp={step:1});const steps=['Upload','Match columns','Preview','Confirm','Result'];
 const head=`<div class="page-head"><div><div class="eyebrow"><a href="#households">${t('households')}</a> / Import</div><h1 class="h1">Import records</h1><p class="lede">Imports existing barangay or LGU household records (for example the RBI list). New households start as Imported until staff verify details and collect consent.</p></div></div>
 <div class="steps">${steps.map((s,i)=>`<div class="${I.step===i+1?'on':I.step>i+1?'done':''}"><b>${I.step>i+1?icon('check',13):i+1}</b>${s}</div>`).join('')}</div>`;
 if(I.step===1)return head+`<section class="card stack"><h2 class="h2">Choose a file</h2><p class="muted" style="margin:0">CSV or Excel, one row per person. Rows that share a household number become one household.</p>
  <label class="field" for="imp-file"><span>File</span><input type="file" id="imp-file" accept=".csv,.xlsx,.xls,text/csv" onchange="A.impFile(this.files[0])"></label>
  <div class="row"><select class="sel-inline" id="imp-brgy" aria-label="Barangay for these records">${DB.brgys.filter(b=>S.user.role==='admin'||b.id===S.user.brgy).map(b=>`<option value="${b.id}" ${I.brgy===b.id?'selected':''}>Into Brgy. ${esc(b.name)}</option>`).join('')}</select><button class="btn" onclick="A.impSample()">${icon('file',16)}Use the sample file (12 rows)</button></div>
  <div class="err" id="imp-err">${esc(I.err||'')}</div></section>`;
 if(I.step===2)return head+`<section class="card stack"><div class="split"><h2 class="h2">Match file columns to system fields</h2><span class="sm muted">${esc(I.file)} · ${plural(I.rows.length,'row')}</span></div>
  <div class="grid2">${IFIELDS.map(([k,l,req])=>`<label class="field" for="map-${k}"><span>${l}${req?' <span style="color:var(--bad-ink)">*</span>':''}</span><select id="map-${k}" onchange="A.impMap('${k}',this.value)"><option value="">Not in file</option>${I.headers.map((h,i)=>`<option value="${i}" ${String(I.map[k])===String(i)?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div>
  <div class="err" id="map-err"></div><div class="actions"><button class="btn" onclick="A.impStep(1)">Back</button><button class="btn btn-primary" onclick="A.impPreview()">Preview</button></div></section>`;
 if(I.step===3){const a=I.analyzed,er=a.filter(o=>o.errs.length).length,du=a.filter(o=>o.dup).length;
  return head+`<div class="stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat"><div class="stat-label">Rows ready</div><div class="stat-num">${a.length-er-du}</div></div><div class="stat"><div class="stat-label">Possible duplicates</div><div class="stat-num" style="color:var(--warn-ink)">${du}</div><div class="stat-sub">Will link to the existing household</div></div><div class="stat"><div class="stat-label">Rows with errors</div><div class="stat-num" style="color:var(--bad-ink)">${er}</div><div class="stat-sub">Will be skipped</div></div></div>
  <div class="tbl-wrap"><table><thead><tr><th>#</th><th>Household no.</th><th>Name</th><th>Birthdate</th><th>Relationship</th><th>Purok</th><th>Needs</th><th>Check</th></tr></thead><tbody>${a.map(o=>`<tr class="${o.errs.length?'err-row':o.dup?'warn-row':''}"><td class="num">${o.i+2}</td><td class="mono">${esc(o.ref)||'—'}</td><td>${esc(o.name)||'—'}</td><td class="num">${esc(o.birthRaw)||'—'}</td><td>${esc(o.rel)}</td><td>${esc(o.purok)}</td><td>${o.needs.map(n=>tag(n)).join(' ')}</td><td class="sm">${o.errs.length?`<b style="color:var(--bad-ink)">${o.errs.join('; ')}</b>`:o.dup?`<b style="color:var(--warn-ink)">Matches ${o.dup.code}</b>`:'<span style="color:var(--ok-ink)">OK</span>'}</td></tr>`).join('')}</tbody></table></div>
  <div class="actions"><button class="btn" onclick="A.impStep(2)">Back</button><button class="btn btn-primary" onclick="A.impStep(4)">Continue</button></div>`}
 if(I.step===4){const p=importPlan();return head+`<section class="card stack"><h2 class="h2">Ready to import into Brgy. ${esc(brgyOf(I.brgy).name)}</h2>
  <dl class="kv"><dt>New households</dt><dd><b>${p.create.length}</b> (${plural(p.create.reduce((s,g)=>s+g.length,0),'member')})</dd><dt>Linked to existing</dt><dd>${p.link.length}</dd><dt>Skipped</dt><dd>${p.skip} rows with errors or no household head</dd></dl>
  <div class="alert info">${icon('info',16)}New households get status Imported and a QR card in the print queue. Staff still need to verify details and collect consent.</div>
  <div class="actions"><button class="btn" onclick="A.impStep(3)">Back</button><button class="btn btn-primary" onclick="A.impConfirm()">Confirm import</button></div></section>`}
 const r=I.result;return head+`<section class="card stack"><div class="row"><span class="done-mark" style="margin:0;width:44px;height:44px">${icon('check',24)}</span><h2 class="h2">Import finished</h2></div>
  <dl class="kv"><dt>Created</dt><dd><b>${plural(r.created,'household')}</b>, ${plural(r.members,'member')}</dd><dt>Duplicates linked</dt><dd>${r.linked}${r.linkedCodes.length?` (${r.linkedCodes.join(', ')})`:''}</dd><dt>Errors skipped</dt><dd>${plural(r.errors,'row')}</dd></dl>
  <div class="actions"><button class="btn" onclick="A.impReset()">Import another file</button><a class="btn" href="#cards" onclick="S.cardScope='queue'">${icon('printer',16)}Print new cards</a><a class="btn btn-primary" href="#households" onclick="S.hf.status='imported'">View imported households</a></div></section>`};
function importPlan(){const I=S.imp,create=[],link=[];let skip=0;
 Object.values(I.groups).forEach(g=>{const ok=g.filter(o=>!o.errs.length);skip+=g.length-ok.length;const head=ok.find(o=>/head/i.test(o.rel));if(!head){skip+=ok.length;return}if(head.dup){link.push(head.dup);return}create.push(ok)});
 skip+=I.analyzed.filter(o=>!o.ref).length;return {create,link,skip}}

/* ---------- Walk-in (web + phone share this form) ---------- */
function newWalkin(mode){const b=S.user.brgy==='all'?(S.brgy!=='all'?S.brgy:'b1'):S.user.brgy;return {mode,step:1,brgy:b,m:[{name:'',birth:'',sex:'',rel:'Head',needs:[],note:''}],location:'',purok:'',phone:'',consent:false,signed:false,err:''}}
function WalkinForm(){const W=S.wk,mob=W.mode==='mobile';const steps=['Family','Special needs','Location','Consent','Issue card'];
 const st=`<div class="steps">${steps.map((s,i)=>`<div class="${W.step===i+1?'on':W.step>i+1?'done':''}"><b>${W.step>i+1?icon('check',13):i+1}</b>${mob&&W.step!==i+1?'':s}</div>`).join('')}</div>`;
 let body='';
 if(W.step===1)body=`<h2 class="h2">Head of family and members</h2>${W.m.map((m,i)=>`<div class="member-row"><label class="field full" for="wm-n${i}"><span>${i===0?'Head of family':'Member '+(i+1)} full name</span><input id="wm-n${i}" value="${esc(m.name)}" oninput="A.wkM(${i},'name',this.value)" autocomplete="off"></label><label class="field" for="wm-b${i}"><span>Birthdate${i===0?' *':''}</span><input type="date" id="wm-b${i}" max="${today()}" value="${esc(m.birth)}" onchange="A.wkM(${i},'birth',this.value)"></label><label class="field" for="wm-s${i}"><span>Sex</span><select id="wm-s${i}" onchange="A.wkM(${i},'sex',this.value)"><option value="">—</option><option value="F" ${m.sex==='F'?'selected':''}>Female</option><option value="M" ${m.sex==='M'?'selected':''}>Male</option></select></label>${i===0?'<div></div>':`<label class="field" for="wm-r${i}"><span>Relationship</span><select id="wm-r${i}" onchange="A.wkM(${i},'rel',this.value)">${['Spouse','Son','Daughter','Father','Mother','Grandchild','Sibling','Relative','Other'].map(r=>`<option ${m.rel===r?'selected':''}>${r}</option>`).join('')}</select></label>`}${i>0?`<button class="icon-btn" aria-label="Remove member ${i+1}" onclick="A.wkDel(${i})">${icon('x',18)}</button>`:'<div></div>'}</div>`).join('')}<button class="btn" onclick="A.wkAdd()">${icon('plus',16)}Add member</button>`;
 if(W.step===2)body=`<h2 class="h2">Special needs</h2><p class="muted sm" style="margin:0">Seniors (60+) and infants (under 2) are marked from the birthdate. These details are sensitive and only shown to authorized roles.</p>${W.m.map((m,i)=>`<div class="ph-card stack" style="padding:14px"><b>${esc(m.name||'Member '+(i+1))} <span class="muted sm">${ageLabel(m.birth)}</span></b><div class="needs-grid">${Object.keys(NEEDS).map(n=>`<button type="button" class="need-toggle t-${n} ${m.needs.includes(n)?'on':''}" aria-pressed="${m.needs.includes(n)}" onclick="A.wkNeed(${i},'${n}')">${icon(NEEDS[n][1],15)}${NEEDS[n][0]}</button>`).join('')}</div>${m.needs.includes('MEDICAL')?`<label class="field" for="wm-note${i}"><span>Medical note (restricted)</span><input id="wm-note${i}" value="${esc(m.note)}" oninput="A.wkM(${i},'note',this.value)" placeholder="e.g. needs insulin"></label>`:''}</div>`).join('')}`;
 if(W.step===3)body=`<h2 class="h2">Current location</h2><p class="muted sm" style="margin:0">No fixed address is needed. Write where the family is staying now.</p><label class="field" for="wk-loc"><span>Where are they staying? *</span><textarea id="wk-loc" oninput="S.wk.location=this.value" placeholder="e.g. Living under the bridge at Purok 4">${esc(W.location)}</textarea></label>
  <div class="grid2"><label class="field" for="wk-b"><span>Barangay</span><select id="wk-b" onchange="S.wk.brgy=this.value">${DB.brgys.filter(b=>S.user.brgy==='all'||b.id===S.user.brgy).map(b=>`<option value="${b.id}" ${W.brgy===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><label class="field" for="wk-p"><span>Purok (if known)</span><input id="wk-p" type="number" min="1" max="12" value="${esc(W.purok)}" oninput="S.wk.purok=this.value"></label></div>
  <label class="field" for="wk-ph"><span>Phone (optional)</span><input id="wk-ph" type="tel" value="${esc(W.phone)}" oninput="S.wk.phone=this.value" placeholder="09XX XXX XXXX"></label>`;
 if(W.step===4)body=`<h2 class="h2">Consent</h2><div class="ph-card sm" style="line-height:1.6">${esc(DB.settings.consent)}</div><label class="check"><input type="checkbox" id="wk-c" ${W.consent?'checked':''} onchange="S.wk.consent=this.checked"><span>The head of family read or heard this and agrees.</span></label>
  <div class="field"><span>Signature (optional, draw with finger or mouse)</span><canvas class="sig" id="sig" aria-label="Signature pad"></canvas><div class="row"><button class="btn btn-sm" onclick="A.sigClear()">Clear signature</button><span class="sm muted">Recorded by ${esc(S.user.name)} · ${fmtDT(Date.now())}</span></div></div>`;
 if(W.step===5){const c=needCounts(W.m);body=`<h2 class="h2">Review and issue card</h2><dl class="kv"><dt>Head of family</dt><dd><b>${esc(W.m[0].name)}</b> · ${ageLabel(W.m[0].birth)}</dd><dt>Members</dt><dd>${W.m.length}: ${W.m.map(m=>esc(m.name)).join(', ')}</dd><dt>Special needs</dt><dd>${Object.keys(c).filter(k=>c[k]).map(k=>tag(k,c[k])).join(' ')||'None'}</dd><dt>Location</dt><dd>${esc(W.location)}</dd><dt>Barangay</dt><dd>${esc(brgyOf(W.brgy).name)}</dd><dt>Consent</dt><dd>Given${W.signed?', signed':''}</dd></dl>
  <div class="alert info">${icon('shield',16)}We check name and birthdate for an existing record before issuing the card. Status will be Walk-in (pending) until an officer verifies.</div>`}
 if(W.step===6){const h=hh(W.doneId),c=cardOf(h);body=`<div class="stack" style="align-items:center;text-align:center"><span class="done-mark">${icon('check',32)}</span><h2 class="h2">Card issued to ${esc(headOf(h).name)}</h2><p class="muted" style="margin:0">Status: Walk-in (pending). The family can receive relief now. ${mob?(S.online?'Uploaded.':'Saved on this phone. Will upload when signal returns.'):''}</p>${cardFront(h,c)}<p class="sm muted" style="margin:0">${mob?'Show this temporary digital QR to the family. A printed card can follow from the Barangay Hall.':'Print this card now, or it stays in the print queue.'}</p></div>`}
 const nav=W.step<=5?`<div class="err" role="alert">${esc(W.err)}</div><div class="actions" style="justify-content:space-between">${W.step>1?`<button class="btn" onclick="A.wkStep(-1)">Back</button>`:`<button class="btn" onclick="A.wkCancel()">Cancel</button>`}${W.step<5?`<button class="btn btn-primary" onclick="A.wkStep(1)">Next</button>`:`<button class="btn btn-accent" onclick="A.wkSave()">${icon('qr',16)}Save and issue card</button>`}</div>`
  :`<div class="actions" style="justify-content:center">${mob?`<button class="btn" onclick="A.sc('home')">Done</button><button class="btn btn-primary" onclick="A.scOpen('${W.doneId}')">Open household</button>`:`<button class="btn" onclick="A.printCards(['${W.doneId}'])">${icon('printer',16)}Print card</button><button class="btn" onclick="A.startWalkin('web')">Register another</button><button class="btn btn-primary" onclick="A.openHH('${W.doneId}')">Open household</button>`}</div>`;
 return `${st}<div class="${mob?'stack':'card stack'}">${body}${nav}</div>`}
VIEWS.walkin=function(){if(!S.wk||S.wk.mode!=='web')S.wk=newWalkin('web');return `<div class="page-head"><div><div class="eyebrow"><a href="#households">${t('households')}</a> / Walk-in</div><h1 class="h1">Register walk-in</h1><p class="lede">No one is turned away. The family gets a card today and an officer verifies later.</p></div></div>${WalkinForm()}`};

/* ---------- Verification queue ---------- */
VIEWS.verify=function(){const list=DB.households.filter(h=>h.status==='pending'&&vis(h)&&brgyOk(h.brgy)).sort((a,b)=>a.createdAt-b.createdAt);
 return `<div class="page-head"><div><div class="eyebrow">Walk-ins</div><h1 class="h1">${t('verify')}</h1><p class="lede">Walk-in households waiting for an officer. They already have temporary access to relief.</p></div><span class="chip">${plural(list.length,'household')} waiting</span></div>
 <div class="tbl-wrap"><table><thead><tr><th>Household ID</th><th>Head of family</th><th class="r">Members</th><th class="hide-sm">Location</th><th>Needs</th><th class="hide-sm">Registered</th><th>Actions</th></tr></thead><tbody>
 ${list.map(h=>`<tr><td class="mono"><a href="#" onclick="event.preventDefault();A.openHH('${h.id}')">${h.code}</a>${h.infoRequested?'<span class="sub" style="color:var(--warn-ink)">Info requested</span>':''}</td><td><b>${esc(headOf(h).name)}</b><span class="sub">${ageLabel(headOf(h).birth)}</span></td><td class="r num">${h.members.length}</td><td class="hide-sm sm">${esc(h.location)}</td><td>${hhTags(h)}</td><td class="hide-sm sm">${ago(h.createdAt)}<span class="sub">${esc(h.createdBy)} · ${h.device}</span></td>
 <td><div class="actions">${canEditHH()?`<button class="btn btn-ok btn-sm" onclick="A.verify('${h.id}')">${icon('check',14)}Verify</button><button class="btn btn-sm" onclick="A.modal('info',{id:'${h.id}'})">Request info</button><button class="btn btn-sm" onclick="A.modal('merge',{id:'${h.id}',q:''})">${icon('merge',14)}Merge</button><button class="btn btn-sm btn-danger" onclick="A.modal('reject',{id:'${h.id}'})">Reject</button>`:'<span class="muted sm">View only</span>'}</div></td></tr>`).join('')||'<tr><td colspan="7" class="empty">No walk-ins waiting. New walk-ins appear here after their phone syncs.</td></tr>'}
 </tbody></table></div>`};

/* ---------- QR cards ---------- */
function cardScopeList(){const sc=S.cardScope;const base=DB.households.filter(h=>liveHH(h)&&brgyOk(h.brgy)&&h.status!=='inactive');
 if(sc==='selected')return base.filter(h=>S.sel.has(h.id));if(sc.startsWith('purok:'))return base.filter(h=>String(h.purok)===sc.slice(6));
 return base.filter(h=>{const c=cardOf(h);return c&&c.status==='Active'&&!c.printed})}
VIEWS.cards=function(){const list=cardScopeList();const maxP=Math.max(...DB.brgys.filter(b=>brgyOk(b.id)).map(b=>b.puroks));const show=list.slice(0,6);
 return `<div class="page-head"><div><div class="eyebrow">Cards</div><h1 class="h1">QR card print</h1><p class="lede">Credit-card size (85.6 × 54 mm), waterproof PVC or laminated. No names or medical details are printed.</p></div>
 <div class="actions"><button class="btn" ${list.length?'':'disabled'} onclick="A.markPrinted()">${icon('check',16)}Mark ${plural(list.length,'card')} as printed</button><button class="btn btn-primary" ${list.length?'':'disabled'} onclick="A.printCards()">${icon('printer',16)}Print ${plural(list.length,'card')}</button></div></div>
 <div class="filters"><div class="seg"><button class="${S.cardScope==='queue'?'on':''}" onclick="A.cardScope('queue')">Print queue</button><button class="${S.cardScope==='selected'?'on':''}" onclick="A.cardScope('selected')">Selected (${S.sel.size})</button></div>
 <select class="sel-inline" aria-label="Whole purok" onchange="A.cardScope(this.value)"><option value="">Whole purok…</option>${Array.from({length:maxP},(_,i)=>`<option value="purok:${i+1}" ${S.cardScope==='purok:'+(i+1)?'selected':''}>Purok ${i+1}</option>`).join('')}</select>
 <div class="search" style="max-width:340px">${icon('search',17)}<input id="reprint-q" placeholder="Reprint one card: type household ID" onkeydown="if(event.key==='Enter')A.reprint(this.value)" aria-label="Reprint one card by household ID"></div></div>
 <div class="alert info">${icon('info',16)}<span>${plural(list.length,'card')} in this batch.${list.length>6?' Showing the first 6.':''} The printer gets one sheet with fronts, then backs. Opening the app as a file in Chrome or Edge gives the best print.</span></div>
 ${show.length?`<div class="cards-preview">${show.map(h=>{const c=cardOf(h);return `<div class="stack" style="gap:8px"><div class="pair">${cardFront(h,c)}${cardBack(h,c)}</div><span class="sm muted">${esc(headOf(h).name)} · ${h.code}</span></div>`}).join('')}</div>`:'<div class="card empty">Nothing in this batch. Choose a purok, or select households in the Households list.</div>'}`};

/* ---------- Centers ---------- */
VIEWS.centers=function(){const cs=centersV();
 return `<div class="page-head"><div><div class="eyebrow">Operations</div><h1 class="h1">${t('centers')}</h1><p class="lede">Open a center when families start arriving. Click a center to see who is inside.</p></div>${S.user.role==='admin'?`<button class="btn btn-primary" onclick="A.modal('center',{})">${icon('plus',16)}Add center</button>`:''}</div>
 <div class="grid3">${cs.map(c=>{const o=occ(c.id),st=c.status==='Closed'?'Closed':o>=c.capacity?'Full':'Open';const ms=activeAt(c.id).flatMap(x=>hh(x.hh).members);const v=ms.filter(m=>m.needs.length).length;
  return `<button class="card" style="text-align:left;cursor:pointer;display:flex;flex-direction:column;gap:12px" onclick="A.drawer('center','${c.id}')"><div class="split"><div><h2 class="h2">${esc(c.name)}</h2><div class="sm muted">Brgy. ${esc(brgyOf(c.brgy).name)} · ${esc(c.contact)}</div></div><span class="badge ${st==='Open'?'b-ok':st==='Full'?'b-bad':'b-dark'}">${st}</span></div>
  <div><div class="split"><span class="stat-num" style="font-size:26px">${o}<small>/ ${c.capacity} people</small></span><span class="sm muted">${Math.round(o/c.capacity*100)}%</span></div>${occBar(o,c.capacity)}</div>
  <div class="sm muted">${plural(activeAt(c.id).length,'household')} · ${v} vulnerable</div></button>`}).join('')}</div>`};
function CenterDrawer(c){const list=activeAt(c.id).map(x=>({ci:x,h:hh(x.hh)})).sort((a,b)=>b.ci.inAt-a.ci.inAt);const o=occ(c.id),ms=list.flatMap(x=>x.h.members),nc=needCounts(ms);
 const log=DB.checkins.filter(x=>x.center===c.id&&vis(x)).flatMap(x=>[{at:x.inAt,t:'In',h:x.hh,d:x.device},...(x.outAt?[{at:x.outAt,t:'Out',h:x.hh,d:x.device}]:[])]).sort((a,b)=>b.at-a.at).slice(0,15);
 const devs=[...new Set(DB.checkins.filter(x=>x.center===c.id&&Date.now()-x.inAt<2*D).map(x=>x.device))];
 const adm=['admin','officer'].includes(S.user.role);
 const tb=[['people','Checked in',list.length],['log','Log'],['devices','Devices',devs.length]];const tk=tabKey('center',tb);let panel='';
 if(tk==='people'){const q=norm(S.centerQ||'');const fl=q?list.filter(({h})=>hhSearchText(h).includes(q)):list;
  panel=`${list.length>8?`<div class="search">${icon('search',17)}<input type="search" id="ctr-q" value="${esc(S.centerQ||'')}" placeholder="Filter by name or household ID" oninput="A.centerQ(this.value)" aria-label="Filter checked-in households"></div>`:''}
  <div class="tbl-wrap" id="ctr-list"><table><thead><tr><th>Household</th><th class="r">People</th><th class="hide-sm">Needs</th><th>Since</th><th></th></tr></thead><tbody>${fl.map(({ci,h})=>`<tr><td><a href="#" class="mono" onclick="event.preventDefault();A.openHH('${h.id}')">${h.code}</a><span class="sub">${esc(headOf(h).name)}</span></td><td class="r num">${h.members.length}</td><td class="hide-sm">${hhTags(h)}</td><td class="sm">${fmtTime(ci.inAt)}<span class="sub">${ago(ci.inAt)}</span></td><td>${adm?`<button class="btn btn-sm" onclick="A.webCheckout('${ci.id}')">Check out</button>`:''}</td></tr>`).join('')||`<tr><td colspan="5" class="empty">${q?'No match.':'No one checked in.'}</td></tr>`}</tbody></table></div>`}
 if(tk==='log')panel=`<section class="card"><div class="list">${log.map(e=>`<div class="list-item sm"><span class="badge ${e.t==='In'?'b-ok':'b-imported'}">${e.t}</span><div class="grow"><span class="mono">${hh(e.h).code}</span> · ${esc(headOf(hh(e.h)).name)}</div><span class="muted hide-sm">${fmtDT(e.at)}</span><span class="mono faint">${e.d}</span></div>`).join('')||'<div class="empty">No check-ins yet.</div>'}</div></section>`;
 if(tk==='devices')panel=`<section class="card"><div class="list">${devs.map(d=>{const x=deviceOf(d);return `<div class="list-item sm"><span class="dot ${x.status==='Online'?'ok':'warn'}"></span><div class="grow"><b>${d}</b> · ${esc(x.name)}<span class="sub">${esc(userById(x.user)?.name||'')}</span></div><span class="muted">${x.status}</span></div>`}).join('')||'<div class="empty">No devices used here in the last 2 days.</div>'}</div></section>`;
 return `<div class="drawer-head" style="flex-direction:column;gap:14px;padding-bottom:0"><div class="row" style="width:100%;flex-wrap:nowrap;align-items:flex-start"><div style="flex:1;min-width:0"><div class="eyebrow">Evacuation center · Brgy. ${esc(brgyOf(c.brgy).name)}</div><div class="h1">${esc(c.name)}</div><div class="sm muted" style="margin-top:4px">${esc(c.location)} · ${esc(c.contact)}</div></div>${adm?`<button class="btn btn-sm" onclick="A.centerStatus('${c.id}')">${c.status==='Closed'?'Open center':'Close center'}</button>`:''}<button class="icon-btn" aria-label="Close" onclick="A.close()">${icon('x',20)}</button></div>
  <div style="width:100%"><div class="split"><span class="stat-num" style="font-size:26px">${o}<small>/ ${c.capacity} people</small></span><span class="badge ${c.status==='Closed'?'b-dark':o>c.capacity?'b-bad':o>=c.capacity*.85?'b-pending':'b-ok'}">${c.status==='Closed'?'Closed':o>c.capacity?'Over capacity':o>=c.capacity*.85?'Almost full':'Space available'}</span></div><div style="margin-top:8px">${occBar(o,c.capacity)}</div>
  <div class="needcount" style="margin-top:12px">${Object.keys(nc).map(k=>tag(k,nc[k]).replace(/×\d+/,'')+`<b class="num" style="margin:0 8px 0 -2px">${nc[k]}</b>`).join('')}</div></div>
  <div style="width:100%">${tabs('center',tb,'Center sections')}</div></div>
 <div class="drawer-body"><div class="tab-panel">${panel}</div></div>`}

/* ---------- Inventory ---------- */
VIEWS.inventory=function(){const ed=canStock();const now=Date.now();
 const rate=i=>DB.moves.filter(m=>m.item===i.id&&m.type==='OUT'&&now-m.at<3*D).reduce((s,m)=>s+m.qty,0)/3;
 return `<div class="page-head"><div><div class="eyebrow">Operations</div><h1 class="h1">${t('inventory')}</h1><p class="lede">Stock goes down automatically when a scanner records relief received.</p></div>
 ${ed?`<div class="actions"><button class="btn" onclick="A.modal('item',{})">${icon('plus',16)}Add item</button><button class="btn" onclick="A.modal('stock',{type:'OUT'})">Record stock out</button><button class="btn btn-primary" onclick="A.modal('stock',{type:'IN'})">${icon('plus',16)}Record stock in</button></div>`:''}</div>
 ${tabs('inv',[['items','Items',DB.items.length],['moves','Stock movements',DB.moves.length]],'Inventory sections')}
 ${tabKey('inv',[['items'],['moves']])==='items'?`<div class="tab-panel"><div class="tbl-wrap"><table><thead><tr><th>Item</th><th class="hide-sm">Category</th><th class="r">Stock on hand</th><th class="r hide-sm">Reorder level</th><th class="r">Lasts about</th><th class="hide-sm">Last updated</th><th></th></tr></thead><tbody>
 ${DB.items.map(i=>{const r=rate(i),low=i.stock<i.reorder;return `<tr><td><b>${esc(i.name)}</b><span class="sub">per ${esc(i.unit)}</span></td><td class="hide-sm">${esc(i.category)}</td><td class="r num"><b>${fmtN(i.stock)}</b></td><td class="r num hide-sm">${fmtN(i.reorder)}</td><td class="r num">${r>0?`${Math.max(0,i.stock/r).toFixed(1)} days`:'<span class="faint">No recent use</span>'}</td><td class="hide-sm sm muted">${ago(i.updatedAt)}</td><td>${low?'<span class="badge b-pending">Low stock</span>':'<span class="badge b-ok">OK</span>'}</td></tr>`}).join('')}
 </tbody></table></div></div>`
 :`<div class="tab-panel"><section class="card"><div class="list">${DB.moves.slice().sort((a,b)=>b.at-a.at).slice(0,S.movesN).map(m=>`<div class="list-item sm"><span class="badge ${m.type==='IN'?'b-ok':'b-imported'}">${m.type}</span><div class="grow"><b>${m.type==='IN'?'+':'−'}${fmtN(m.qty)} ${esc(itemOf(m.item).name)}</b> · ${esc(m.source)}<span class="sub">${esc(m.user)}</span></div><span class="muted">${fmtDT(m.at)}</span></div>`).join('')}</div>
 ${DB.moves.length>S.movesN?`<div class="pager"><span>Showing ${S.movesN} of ${fmtN(DB.moves.length)}</span><button class="btn btn-sm" onclick="S.movesN+=25;render()">Show more</button></div>`:''}</section></div>`}`};

/* ---------- Distributions ---------- */
VIEWS.distributions=function(){const rs=DB.rounds.filter(r=>brgyOk(centerOf(r.center).brgy)).sort((a,b)=>b.dateAt-a.dateAt);
 return `<div class="page-head"><div><div class="eyebrow">Operations</div><h1 class="h1">${t('distributions')}</h1><p class="lede">One claim per household per round. A second scan shows Already received.</p></div><button class="btn btn-primary" onclick="A.modal('round',{})">${icon('plus',16)}Create round</button></div>
 <div class="tbl-wrap"><table><thead><tr><th>Round</th><th>Item</th><th class="hide-sm">Center</th><th class="r">Target</th><th class="r">Served</th><th class="r">Remaining</th><th style="min-width:120px">Progress</th><th>Status</th></tr></thead><tbody>
 ${rs.map(r=>{const tg=roundTarget(r).size,sv=roundDists(r.id).length;return `<tr class="click" onclick="A.drawer('round','${r.id}')"><td class="mono">${r.code}<span class="sub" style="font-family:var(--font)">${fmtDT(r.dateAt)}</span></td><td><b>${esc(itemOf(r.item).name)}</b><span class="sub">${r.qty} per household</span></td><td class="hide-sm">${esc(centerOf(r.center).name)}</td><td class="r num">${tg}</td><td class="r num">${sv}</td><td class="r num">${Math.max(0,tg-sv)}</td><td><div class="bar"><i class="navy" style="width:${tg?(sv/tg*100).toFixed(0):0}%"></i></div></td><td><span class="badge ${r.status==='Open'?'b-ok':'b-dark'}">${r.status}</span></td></tr>`}).join('')}
 </tbody></table></div>`};
function RoundDrawer(r){const ds=roundDists(r.id),served=new Set(ds.map(d=>d.hh)),tg=[...roundTarget(r)],ns=tg.filter(id=>!served.has(id)).map(hh);const it=itemOf(r.item);
 const tb=[['todo','Not yet served',ns.length],['done','Served',ds.length]];const tk=tabKey('round',tb);
 const panel=tk==='todo'?`<section class="card"><div class="list">${ns.map(h=>`<div class="list-item sm click" style="cursor:pointer" onclick="A.openHH('${h.id}')"><span class="dot warn"></span><div class="grow"><span class="mono">${h.code}</span> · ${esc(headOf(h).name)}</div>${hhTags(h)}</div>`).join('')||'<div class="empty">Everyone checked in here is served.</div>'}</div></section>`
  :`<section class="card"><div class="list">${ds.slice().sort((a,b)=>b.at-a.at).map(d=>`<div class="list-item sm"><span class="dot ok"></span><div class="grow"><span class="mono">${hh(d.hh).code}</span> · ${esc(headOf(hh(d.hh)).name)}</div><span class="muted">${fmtTime(d.at)}</span><span class="mono faint">${d.device}</span></div>`).join('')||'<div class="empty">No one served yet.</div>'}</div></section>`;
 return `<div class="drawer-head" style="flex-direction:column;gap:14px;padding-bottom:0"><div class="row" style="width:100%;flex-wrap:nowrap;align-items:flex-start"><div style="flex:1;min-width:0"><div class="eyebrow">Distribution round · ${fmtDT(r.dateAt)}</div><div class="h1">${r.code} · ${esc(it.name)}</div><div class="sm muted" style="margin-top:4px">${esc(centerOf(r.center).name)} · ${r.qty} ${esc(it.unit)}${r.qty>1?'s':''} per household · one claim per household</div></div><button class="icon-btn" aria-label="Close" onclick="A.close()">${icon('x',20)}</button></div>
  <div class="mini-stats" style="width:100%"><div><span>Served</span><b>${ds.length}</b></div><div><span>Not yet</span><b>${ns.length}</b></div><div><span>Given out</span><b>${fmtN(ds.length*r.qty)}</b></div></div>
  <div class="actions" style="width:100%">${r.status==='Open'?`<button class="btn btn-sm" onclick="A.closeRound('${r.id}')">Close round</button>`:'<span class="badge b-dark">Closed</span>'}<button class="btn btn-sm" onclick="A.copyRoundList('${r.id}')">${icon('copy',15)}Copy not-served list</button></div>
  <div style="width:100%">${tabs('round',tb,'Round sections')}</div></div>
 <div class="drawer-body"><div class="tab-panel">${panel}</div></div>`}

/* ---------- Reports ---------- */
const REPORTS={
 evacuees:['Evacuee list',()=>{const rows=[];centersV().forEach(c=>activeAt(c.id).forEach(ci=>{const h=hh(ci.hh);h.members.forEach(m=>rows.push([c.name,h.code,m.name,ageGroup(m.birth),m.sex,m.rel,m.needs.map(n=>NEEDS[n][0]).join('; '),fmtDT(ci.inAt)]))}));return {cols:['Center','Household ID','Name','Age group','Sex','Relationship','Special needs','Checked in'],rows,sum:`${plural(rows.length,'person','people')} in ${plural(new Set(rows.map(r=>r[1])).size,'household')}`}}],
 distribution:['Distribution report',()=>{const rows=DB.rounds.filter(r=>brgyOk(centerOf(r.center).brgy)).map(r=>{const tg=roundTarget(r).size,sv=roundDists(r.id).length;return [r.code,fmtDate(r.dateAt),centerOf(r.center).name,itemOf(r.item).name,r.qty,tg,sv,tg-sv,sv*r.qty]});return {cols:['Round','Date','Center','Item','Qty per household','Target households','Served','Remaining','Total given'],rows,sum:`${plural(rows.length,'round')}, ${fmtN(rows.reduce((s,r)=>s+r[6],0))} household claims`}}],
 inventory:['Inventory movement',()=>{const rows=DB.moves.slice().sort((a,b)=>b.at-a.at).map(m=>[fmtDT(m.at),itemOf(m.item).name,m.type,m.qty,m.source,m.user]);return {cols:['Time','Item','Type','Quantity','Source / reason','Recorded by'],rows,sum:`${plural(rows.length,'movement')}`}}],
 vulnerable:['Vulnerable groups',()=>{const rows=[];centersV().forEach(c=>activeAt(c.id).forEach(ci=>{const h=hh(ci.hh);h.members.filter(m=>m.needs.length).forEach(m=>rows.push([c.name,h.code,m.name,ageLabel(m.birth),m.needs.map(n=>NEEDS[n][0]).join('; '),seesMedical()?m.note:(m.note?'Restricted':'')]))}));return {cols:['Center','Household ID','Name','Age','Needs','Medical note'],rows,sum:`${plural(rows.length,'vulnerable evacuee')}`}}],
 walkin:['Walk-in verification',()=>{const rows=DB.households.filter(h=>h.source==='walkin'&&vis(h)&&brgyOk(h.brgy)).map(h=>[h.code,headOf(h).name,h.members.length,h.location,STATUS[h.status][0],fmtDT(h.createdAt),h.createdBy,h.device]);return {cols:['Household ID','Head','Members','Location','Status','Registered','Registered by','Device'],rows,sum:`${plural(rows.length,'walk-in')}, ${rows.filter(r=>r[4]!=='Walk-in (pending)').length} resolved`}}]};
VIEWS.reports=function(){const [title,fn]=REPORTS[S.rep]||REPORTS.evacuees;const r=fn();const shown=r.rows.slice(0,100);
 return `<div class="page-head"><div><div class="eyebrow">Reports · ${S.brgy==='all'?'All barangays':'Brgy. '+esc(brgyOf(S.brgy).name)}</div><h1 class="h1">${t('reports')}</h1><p class="lede">Ready-made summaries to print, save as PDF or paste into Excel.</p></div><div class="actions no-print"><button class="btn" onclick="A.copyReport()">${icon('copy',16)}Copy as CSV (Excel)</button><button class="btn btn-primary" onclick="A.printReport()">${icon('printer',16)}Print / save PDF</button></div></div>
 <div class="seg no-print">${Object.keys(REPORTS).map(k=>`<button class="${S.rep===k?'on':''}" onclick="A.rep('${k}')">${REPORTS[k][0]}</button>`).join('')}</div>
 <section class="card"><div class="card-head"><div><h2 class="h2">${title}</h2><div class="sm muted">${r.sum} · generated ${fmtDT(Date.now())} by ${esc(S.user.name)}</div></div></div>
 <div class="tbl-wrap"><table><thead><tr>${r.cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${shown.map(row=>`<tr>${row.map(v=>`<td class="${typeof v==='number'?'num r':''}">${esc(v)}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${r.cols.length}" class="empty">No records.</td></tr>`}</tbody></table></div>
 ${r.rows.length>100?`<div class="pager"><span>Showing 100 of ${fmtN(r.rows.length)} rows. Copy as CSV to get all of them.</span></div>`:''}</section>`};

/* ---------- Devices ---------- */
VIEWS.devices=function(){const errs=DB.syncErrors.filter(e=>!e.resolved);
 return `<div class="page-head"><div><div class="eyebrow">Admin</div><h1 class="h1">${t('devices')}</h1><p class="lede">Scanner phones keep an encrypted copy of the registry and upload when they have signal.</p></div></div>
 ${errs.length?`<section class="card"><h2 class="h2" style="margin-bottom:8px">Sync issues (${errs.length})</h2><div class="list">${errs.map(e=>`<div class="list-item"><span class="dot ${e.kind==='conflict'?'bad':'warn'}"></span><div class="grow"><b>${e.device}</b> · ${esc(e.msg)}<span class="sub sm muted">${fmtDT(e.at)}</span></div>${e.kind==='conflict'?`<button class="btn btn-sm" onclick="A.resolveErr('${e.id}')">Mark reviewed</button>`:`<button class="btn btn-sm" onclick="A.retryErr('${e.id}')">${icon('refresh',14)}Retry now</button>`}</div>`).join('')}</div></section>`:''}
 <div class="tbl-wrap"><table><thead><tr><th>Device</th><th>Assigned user</th><th>Last sync</th><th class="r">Pending records</th><th class="hide-sm">App version</th><th>Status</th><th>Actions</th></tr></thead><tbody>
 ${DB.devices.map(d=>{const p=pendingOf(d.id);return `<tr><td><b class="mono">${d.id}</b><span class="sub">${esc(d.name)}${d.note?' · '+esc(d.note):''}</span></td><td>${esc(userById(d.user)?.name||'—')}</td><td class="sm">${ago(d.lastSyncAt)}</td><td class="r num">${p?`<b style="color:var(--warn-ink)">${p}</b>`:'0'}</td><td class="hide-sm">${d.version}${d.version!=='1.2.0'?' <span class="badge b-pending">Update</span>':''}</td><td><span class="badge ${d.status==='Online'?'b-ok':d.status==='Offline'?'b-pending':'b-dark'}">${d.status}</span></td>
 <td><div class="actions">${d.status!=='Revoked'?`<button class="btn btn-sm" onclick="A.forceSync('${d.id}')">${icon('refresh',14)}Force sync</button><button class="btn btn-sm btn-danger" onclick="A.modal('revoke',{id:'${d.id}'})">Revoke</button>`:'<span class="sm muted">Access removed; local data stays encrypted</span>'}</div></td></tr>`}).join('')}
 </tbody></table></div>`};

/* ---------- Users ---------- */
VIEWS.users=function(){return `<div class="page-head"><div><div class="eyebrow">Admin</div><h1 class="h1">${t('users')}</h1><p class="lede">People who can log in, and what each one is allowed to do.</p></div><button class="btn btn-primary" onclick="A.modal('user',{})">${icon('userplus',16)}Add user</button></div>
 <div class="tbl-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Barangay</th><th class="hide-sm">Last active</th><th>Status</th><th>Actions</th></tr></thead><tbody>
 ${DB.users.map(u=>`<tr><td><div class="row" style="flex-wrap:nowrap"><span class="avatar">${initials(u.name)}</span><div><b>${esc(u.name)}</b><span class="sub">${esc(u.email)}</span></div></div></td><td>${ROLE[u.role].label}</td><td>${u.brgy==='all'?'All':esc(brgyOf(u.brgy).name)}</td><td class="hide-sm sm">${ago(u.lastAt)}</td><td><span class="badge ${u.status==='Active'?'b-ok':'b-dark'}">${u.status}</span></td>
 <td><div class="actions"><button class="btn btn-sm" onclick="A.modal('user',{id:'${u.id}'})">Edit</button>${u.id!==S.user.id?`<button class="btn btn-sm" onclick="A.toggleUser('${u.id}')">${u.status==='Active'?'Disable':'Enable'}</button>`:''}<button class="btn btn-sm" onclick="A.resetPw('${u.id}')">Reset password</button></div></td></tr>`).join('')}
 </tbody></table></div>`};

/* ---------- Audit log ---------- */
VIEWS.audit=function(){const f=S.au,now=Date.now();const users=[...new Set(DB.audit.map(a=>a.user))].sort(),acts=[...new Set(DB.audit.map(a=>a.action))].sort();
 const list=DB.audit.filter(a=>(f.user==='all'||a.user===f.user)&&(f.action==='all'||a.action===f.action)&&(f.range==='all'||now-a.at<(f.range==='1d'?D:7*D)));const size=40,rows=list.slice(f.page*size,(f.page+1)*size);
 return `<div class="page-head"><div><div class="eyebrow">Admin</div><h1 class="h1">${t('audit')}</h1><p class="lede">Every view, edit and export of household data is recorded here.</p></div></div>
 <div class="filters"><select class="sel-inline" aria-label="User" onchange="A.au('user',this.value)"><option value="all">All users</option>${users.map(u=>`<option ${f.user===u?'selected':''}>${esc(u)}</option>`).join('')}</select><select class="sel-inline" aria-label="Action" onchange="A.au('action',this.value)"><option value="all">All actions</option>${acts.map(a=>`<option ${f.action===a?'selected':''}>${esc(a)}</option>`).join('')}</select><select class="sel-inline" aria-label="Date" onchange="A.au('range',this.value)">${[['all','Any date'],['1d','Last 24 hours'],['7d','Last 7 days']].map(([k,l])=>`<option value="${k}" ${f.range===k?'selected':''}>${l}</option>`).join('')}</select></div>
 <div class="tbl-wrap"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Record</th><th class="hide-sm">Device</th></tr></thead><tbody>${rows.map(a=>`<tr><td class="sm num">${fmtDT(a.at)}</td><td>${esc(a.user)}</td><td><span class="badge ${/export|print/.test(a.action)?'b-info':/delet|reject|revok|archiv/.test(a.action)?'b-bad':/view/.test(a.action)?'b-imported':'b-ok'}">${esc(a.action)}</span></td><td class="sm">${esc(a.record)}</td><td class="hide-sm mono sm">${esc(a.device)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No entries match.</td></tr>'}</tbody></table></div>${pager(list.length,f.page,size,'A.auPage')}`};

/* ---------- Settings ---------- */
VIEWS.config=function(){const s=DB.settings;const tb=[['general','Municipality'],['privacy','Data and privacy'],['relief','Relief and alerts'],['data','Backup and reset']];const cur=tabKey('cfg',tb);
 return `<div class="page-head"><div><div class="eyebrow">Admin</div><h1 class="h1">${t('config')}</h1><p class="lede">Changes apply after you press Save settings.</p></div><button class="btn btn-primary" onclick="A.saveSettings()">${icon('check',16)}Save settings</button></div>
 ${tabs('cfg',tb,'Settings sections',true)}
 ${tabPanel('cfg','general',cur,`<section class="card stack"><div class="grid2"><label class="field" for="st-mun"><span>Municipality</span><input id="st-mun" value="${esc(s.municipality)}"></label><label class="field" for="st-prov"><span>Province</span><input id="st-prov" value="${esc(s.province)}"></label></div>
  <h3 class="h3">Barangays</h3>${DB.brgys.map(b=>`<div class="grid2"><label class="field" for="st-bn-${b.id}"><span>Barangay (code ${b.code})</span><input id="st-bn-${b.id}" value="${esc(b.name)}"></label><label class="field" for="st-bh-${b.id}"><span>Barangay Hall contact (printed on cards)</span><input id="st-bh-${b.id}" value="${esc(b.hall)}"></label></div>`).join('')}</section>`)}
 ${tabPanel('cfg','privacy',cur,`<section class="card stack"><label class="field" for="st-ret" style="max-width:280px"><span>Data retention period</span><select id="st-ret">${['1 year','3 years','5 years'].map(o=>`<option ${s.retention===o?'selected':''}>${o}</option>`).join('')}</select></label>
  <label class="field" for="st-consent"><span>Consent form text (read to the head of family at registration)</span><textarea id="st-consent" rows="7">${esc(s.consent)}</textarea></label>
  <label class="field" for="st-lang" style="max-width:380px"><span>Default language</span><select id="st-lang">${[['en','English'],['fil','Filipino'],['bcl','Bikol (draft, needs native-speaker review)']].map(([k,l])=>`<option value="${k}" ${s.lang===k?'selected':''}>${l}</option>`).join('')}</select></label></section>`)}
 ${tabPanel('cfg','relief',cur,`<div class="grid2"><section class="card stack"><h2 class="h2">Relief item categories</h2><div class="tags">${s.categories.map((c,i)=>`<span class="chip">${esc(c)}<button class="icon-btn" style="width:22px;height:22px" aria-label="Remove ${esc(c)}" onclick="A.delCat(${i})">${icon('x',13)}</button></span>`).join('')}</div><form class="row" onsubmit="event.preventDefault();A.addCat()"><input id="st-cat" placeholder="New category" style="max-width:240px" maxlength="40"><button class="btn" type="submit">Add</button></form></section>
  <section class="card stack"><h2 class="h2">Hazard alert banner</h2><p class="muted sm" style="margin:0">Shown in the top bar. Set from official PHIVOLCS / PAGASA bulletins.</p><div class="grid2"><label class="field" for="st-an"><span>Hazard</span><input id="st-an" value="${esc(s.alertName)}"></label><label class="field" for="st-al"><span>Alert level</span><select id="st-al">${['0','1','2','3','4','5'].map(l=>`<option value="${l}" ${s.alert===l?'selected':''}>${l==='0'?'Hide banner':'Level '+l}</option>`).join('')}</select></label></div></section></div>`)}
 ${tabPanel('cfg','data',cur,`<section class="card stack"><h2 class="h2">Backup</h2><p class="muted sm" style="margin:0">Copies the whole registry as JSON. Keep it somewhere safe: it contains personal data.</p><div class="actions"><button class="btn" onclick="A.copyBackup()">${icon('copy',16)}Copy backup (JSON)</button><button class="btn" onclick="A.downloadBackup()">${icon('archive',16)}Download backup file</button></div></section>
  <section class="card stack" style="border-color:color-mix(in srgb,var(--bad) 40%,var(--line))"><h2 class="h2">Reset demo data</h2><p class="muted sm" style="margin:0">Restores the original sample registry and removes everything added in this browser.</p><div><button class="btn btn-danger" onclick="A.modal('reset',{})">Reset demo data</button></div></section>`)}`};

/* ---------- How it works ---------- */
VIEWS.system=function(){const n=(a,b,c='')=>`<div class="node ${c}">${a}<span>${b}</span></div>`,ar=`<div class="arr">${icon('right',18)}</div>`;const tb=[['flows','Key flows'],['arch','Architecture'],['privacy','Privacy and security'],['schema','Database']];const cur=tabKey('sys',tb);
 return `<div class="page-head"><div><div class="eyebrow">System</div><h1 class="h1">How Kaligtasan ID works</h1><p class="lede">Offline-first, private by design, and no one is turned away.</p></div></div>
 ${tabs('sys',tb,'Sections',true)}
 ${tabPanel('sys','flows',cur,`<section class="card stack"><h2 class="h2">Flow C · Relief distribution</h2><div class="flow">${n('Open round','Volunteer picks item and center')}${ar}${n('Scan card','QR holds a random ID only')}${ar}${n('Look up','On the phone, no signal needed','navy')}</div>
  <div class="grid2"><div class="flow">${n('Not yet received','Shown in green','ok')}${ar}${n('Record received','Stock goes down')}${ar}${n('Saved on phone','Synced when signal returns')}</div><div class="flow">${n('Already received','Shown in red with time and device','bad')}${ar}${n('No second claim','Button is disabled')}</div></div></section>
  <section class="card stack"><h2 class="h2">All flows</h2><dl class="kv" style="grid-template-columns:110px 1fr">
  <dt>A · Pre-season</dt><dd>Import records, verify and collect consent, print cards, hand them out.</dd>
  <dt>B · Check-in</dt><dd>Scan card, household found, check in, vulnerable members flagged.</dd>
  <dt>C · Relief</dt><dd>Scan, Not yet received, record, saved offline, synced later.</dd>
  <dt>D · Walk-in</dt><dd>Register, duplicate check, Walk-in (pending), relief now, verified later.</dd>
  <dt>E · Lost card</dt><dd>Search, deactivate old card, issue new, old QR rejected.</dd></dl></section>`)}
 ${tabPanel('sys','arch',cur,`<section class="card stack"><div class="arch">
  <div class="box"><b>${icon('phone',18)} Scanner app</b><ul><li>Installable app (PWA) that opens with no signal</li><li>Local copy of the registry in IndexedDB</li><li>Pending queue with a record ID per scan</li></ul></div>
  <div class="link">${icon('swap',22)}<span>HTTPS sync<br>retries are safe</span></div>
  <div class="box"><b>${icon('cloud',18)} Sync API</b><ul><li>Ignores repeated record IDs</li><li>Flags two claims for one household in one round</li><li>Revoked phones are refused</li></ul></div>
  <div class="link">${icon('swap',22)}<span>SQL</span></div>
  <div class="box"><b>${icon('db',18)} Server database</b><ul><li>Households, members, cards</li><li>Check-ins, rounds, distributions</li><li>Audit log of every view, edit, export</li></ul></div></div>
  <div class="arch" style="grid-template-columns:1fr auto 1fr"><div class="box"><b>${icon('card',18)} QR card</b><ul><li>Random token, no name or medical data</li><li>Lost card is deactivated, old QR rejected</li></ul></div><div class="link">${icon('right',22)}</div><div class="box"><b>${icon('monitor',18)} Web dashboard</b><ul><li>Barangay encoders and DRRM officers</li><li>Access by role and barangay</li></ul></div></div></section>`)}
 ${tabPanel('sys','privacy',cur,`<section class="card stack"><ul class="bullets" style="margin:0;line-height:1.8"><li>Target: Data Privacy Act of 2012 (RA 10173)</li><li>QR contains no personal data</li><li>Health and disability details restricted by role</li><li>Consent captured at registration</li><li>Encrypted on phones and in transit</li><li>Audit log of every view, edit and export</li><li>Data sharing agreement: barangay is the data controller</li><li>Imports existing barangay or LGU records; no direct PSA census access</li></ul></section>`)}
 ${tabPanel('sys','schema',cur,`<section class="card stack"><h2 class="h2">Database schema (simplified SQL)</h2><pre class="sql">CREATE TABLE households (id BIGSERIAL PRIMARY KEY, household_code TEXT UNIQUE, barangay_id INT,
  address_or_location TEXT, status TEXT, source TEXT, consent_signed_at TIMESTAMPTZ, created_at TIMESTAMPTZ);
CREATE TABLE members (id BIGSERIAL PRIMARY KEY, household_id BIGINT REFERENCES households,
  full_name TEXT, birthdate_or_age_group TEXT, sex CHAR(1), relationship TEXT, is_head BOOLEAN);
CREATE TABLE special_needs (id BIGSERIAL PRIMARY KEY, member_id BIGINT REFERENCES members,
  type TEXT CHECK (type IN ('PWD','SENIOR','PREGNANT','INFANT','MEDICAL')));
CREATE TABLE cards (id BIGSERIAL PRIMARY KEY, household_id BIGINT REFERENCES households,
  qr_token TEXT UNIQUE,           -- random, never derived from personal data
  status TEXT, issued_at TIMESTAMPTZ, deactivated_at TIMESTAMPTZ);
CREATE TABLE evacuation_centers (id SERIAL PRIMARY KEY, barangay_id INT, name TEXT, capacity INT, status TEXT);
CREATE TABLE checkins (id BIGSERIAL PRIMARY KEY, household_id BIGINT, center_id INT,
  checked_in_at TIMESTAMPTZ, checked_out_at TIMESTAMPTZ, device_id TEXT);
CREATE TABLE relief_items (id SERIAL PRIMARY KEY, name TEXT, unit TEXT, stock INT, reorder_level INT);
CREATE TABLE stock_movements (id BIGSERIAL PRIMARY KEY, item_id INT, type TEXT CHECK (type IN ('IN','OUT')),
  quantity INT, source TEXT, created_at TIMESTAMPTZ);
CREATE TABLE distribution_rounds (id SERIAL PRIMARY KEY, center_id INT, item_id INT, qty_per_household INT, date DATE);
CREATE TABLE distributions (id BIGSERIAL PRIMARY KEY, round_id INT, household_id BIGINT, device_id TEXT,
  received_at TIMESTAMPTZ, record_uuid UUID UNIQUE,   -- makes sync retries safe
  UNIQUE (round_id, household_id));                  -- one claim per household per round
CREATE TABLE users (id SERIAL PRIMARY KEY, name TEXT, role TEXT, barangay_id INT, status TEXT);
CREATE TABLE devices (id TEXT PRIMARY KEY, user_id INT, name TEXT, last_sync_at TIMESTAMPTZ);
CREATE TABLE audit_log (id BIGSERIAL PRIMARY KEY, user_id INT, action TEXT, record_ref TEXT, created_at TIMESTAMPTZ);</pre></section>`)}`};

/* ---------- Drawer + modals ---------- */
function Drawer(){const d=S.drawer;let inner='';
 if(d.kind==='hh'){const h=hh(d.id);inner=h?HHDrawer(h):''}
 if(d.kind==='center')inner=CenterDrawer(centerOf(d.id));
 if(d.kind==='round')inner=RoundDrawer(roundOf(d.id));
 return `<div class="overlay" onclick="A.close()"></div><aside class="drawer" role="dialog" aria-modal="true">${inner}</aside>`}
function Modal(){const m=S.modal,d=m.data||{};let title='',body='',foot='',wide=false;const h=d.id?hh(d.id):null;
 const cancel=`<button class="btn" onclick="A.closeModal()">Cancel</button>`;
 switch(m.kind){
 case 'edit-hh':{title=`Edit ${h.code}`;wide=true;body=`<div class="grid2"><label class="field" for="e-loc"><span>Address / current location</span><input id="e-loc" value="${esc(h.location)}"></label><label class="field" for="e-ph"><span>Phone</span><input id="e-ph" value="${esc(h.phone)}"></label></div><label class="field" for="e-p" style="max-width:200px"><span>Purok</span><input id="e-p" type="number" min="1" value="${esc(h.purok||'')}"></label>
  <h3 class="h3">Members</h3>${h.members.map((x,i)=>`<div class="member-row"><label class="field" for="e-n${i}"><span>Name</span><input id="e-n${i}" value="${esc(x.name)}"></label><label class="field" for="e-b${i}"><span>Birthdate</span><input type="date" id="e-b${i}" max="${today()}" value="${esc(x.birth||'')}"></label><label class="field" for="e-s${i}"><span>Sex</span><select id="e-s${i}"><option value="F" ${x.sex==='F'?'selected':''}>Female</option><option value="M" ${x.sex==='M'?'selected':''}>Male</option></select></label><label class="field" for="e-r${i}"><span>Relationship</span><input id="e-r${i}" value="${esc(x.rel)}" ${x.head?'readonly':''}></label><div></div><div class="needs-grid full" style="grid-column:1/-1">${Object.keys(NEEDS).map(n=>`<label class="check sm" style="font-size:13px"><input type="checkbox" id="e-${n}-${i}" ${x.needs.includes(n)?'checked':''}>${NEEDS[n][0]}</label>`).join('')}</div></div>`).join('')}
  <div class="row"><input id="e-new" placeholder="Add member: full name" style="max-width:280px"><input type="date" id="e-newb" max="${today()}" style="max-width:180px" aria-label="New member birthdate"></div>`;foot=cancel+`<button class="btn btn-primary" onclick="A.saveHH('${h.id}')">Save changes</button>`;break}
 case 'reissue':title='Reissue card';body=`<p style="margin:0">The current card for <b>${h.code}</b> stops working right away. Scanning the old QR will show "Card not recognized".</p><label class="field" for="ri-r"><span>Reason</span><select id="ri-r"><option value="Lost">Lost</option><option value="Deactivated">Wet or damaged</option><option value="Deactivated">Other</option></select></label>`;foot=cancel+`<button class="btn btn-primary" onclick="A.reissue('${h.id}')">Deactivate old and issue new</button>`;break;
 case 'deactivate':title='Deactivate card';body=`<p style="margin:0">The card for <b>${h.code}</b> will stop working. The household keeps its record and can be given a new card later.</p>`;foot=cancel+`<button class="btn btn-danger" onclick="A.deactivate('${h.id}')">Deactivate card</button>`;break;
 case 'archive':title='Archive household';body=`<p style="margin:0">Archive <b>${h.code}</b> (${esc(headOf(h).name)})? It leaves the active registry and its card stops working. Records stay for the retention period (${esc(DB.settings.retention)}).</p>`;foot=cancel+`<button class="btn btn-danger" onclick="A.archive('${h.id}')">Archive</button>`;break;
 case 'info':title='Request more info';body=`<label class="field" for="ri-note"><span>What is needed?</span><textarea id="ri-note" placeholder="e.g. Bring a barangay certificate or ID for the head of family"></textarea></label>`;foot=cancel+`<button class="btn btn-primary" onclick="A.requestInfo('${h.id}')">Save request</button>`;break;
 case 'reject':title='Reject walk-in';body=`<p style="margin:0">${h.code} · ${esc(headOf(h).name)}</p><label class="field" for="rj-r"><span>Reason (required)</span><textarea id="rj-r"></textarea></label><div class="err" id="rj-err"></div>`;foot=cancel+`<button class="btn btn-danger" onclick="A.reject('${h.id}')">Reject</button>`;break;
 case 'merge':{title='Merge with existing household';wide=true;const q=norm(d.q);const res=q.length>1?DB.households.filter(x=>x.id!==h.id&&liveHH(x)&&x.status!=='pending'&&(norm(x.code).includes(q)||x.members.some(mm=>norm(mm.name).includes(q)))).slice(0,8):[];
  body=`<p style="margin:0">Merge walk-in <b>${h.code}</b> (${esc(headOf(h).name)}, ${plural(h.members.length,'member')}) into an existing household. New members are added; check-ins and relief move over; the walk-in card is deactivated.</p><div class="search">${icon('search',17)}<input id="mg-q" placeholder="Search existing household by name or ID" value="${esc(d.q)}" oninput="A.mergeQ(this.value)" aria-label="Search existing household"></div>
  <div class="list" id="mg-res">${res.map(x=>`<label class="list-item check" style="cursor:pointer"><input type="radio" name="mg" value="${x.id}" ${d.target===x.id?'checked':''} onchange="S.modal.data.target=this.value"><div class="grow"><b class="mono">${x.code}</b> · ${esc(headOf(x).name)}<span class="sub">${x.members.map(mm=>esc(mm.name)).join(', ')}</span></div>${badge(x.status)}</label>`).join('')||(q.length>1?'<div class="empty">No match.</div>':'<div class="muted sm">Type at least 2 letters.</div>')}</div>`;foot=cancel+`<button class="btn btn-primary" onclick="A.merge('${h.id}')">Merge</button>`;break}
 case 'center':title='Add evacuation center';body=`<label class="field" for="c-n"><span>Name</span><input id="c-n"></label><div class="grid2"><label class="field" for="c-b"><span>Barangay</span><select id="c-b">${DB.brgys.map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('')}</select></label><label class="field" for="c-cap"><span>Capacity (people)</span><input id="c-cap" type="number" min="1" value="100"></label></div><label class="field" for="c-l"><span>Location</span><input id="c-l"></label><label class="field" for="c-ct"><span>Contact person</span><input id="c-ct"></label><div class="err" id="c-err"></div>`;foot=cancel+`<button class="btn btn-primary" onclick="A.addCenter()">Add center</button>`;break;
 case 'item':title='Add relief item';body=`<label class="field" for="it-n"><span>Item name</span><input id="it-n"></label><div class="grid2"><label class="field" for="it-c"><span>Category</span><select id="it-c">${DB.settings.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label class="field" for="it-u"><span>Unit</span><input id="it-u" placeholder="pack, liter, kit"></label><label class="field" for="it-s"><span>Starting stock</span><input id="it-s" type="number" min="0" value="0"></label><label class="field" for="it-r"><span>Reorder level</span><input id="it-r" type="number" min="0" value="10"></label></div><div class="err" id="it-err"></div>`;foot=cancel+`<button class="btn btn-primary" onclick="A.addItem()">Add item</button>`;break;
 case 'stock':title=d.type==='IN'?'Record stock in':'Record stock out (adjustment)';body=`<label class="field" for="sk-i"><span>Item</span><select id="sk-i">${DB.items.map(i=>`<option value="${i.id}">${esc(i.name)} (${fmtN(i.stock)} ${i.unit}s)</option>`).join('')}</select></label><div class="grid2"><label class="field" for="sk-q"><span>Quantity</span><input id="sk-q" type="number" min="1"></label><label class="field" for="sk-d"><span>Date</span><input id="sk-d" type="date" value="${today()}"></label></div><label class="field" for="sk-s"><span>${d.type==='IN'?'Source (donor or agency)':'Reason'}</span><input id="sk-s" placeholder="${d.type==='IN'?'e.g. DSWD Region V':'e.g. damaged by flood water'}"></label><div class="err" id="sk-err"></div>`;foot=cancel+`<button class="btn btn-primary" onclick="A.stock('${d.type}')">Save</button>`;break;
 case 'round':{title='Create distribution round';const cs=centersV().filter(c=>c.status!=='Closed');body=`<div class="grid2"><label class="field" for="rd-i"><span>Item</span><select id="rd-i" onchange="A.roundHint()">${DB.items.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></label><label class="field" for="rd-c"><span>Center</span><select id="rd-c" onchange="A.roundHint()">${cs.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label class="field" for="rd-q"><span>Quantity per household</span><input id="rd-q" type="number" min="1" value="1" oninput="A.roundHint()"></label><label class="field" for="rd-d"><span>Date</span><input id="rd-d" type="date" value="${today()}"></label></div><div id="rd-hint"></div>`;foot=cancel+`<button class="btn btn-primary" onclick="A.addRound()">Create round</button>`;break}
 case 'user':{const u=d.id?userById(d.id):{name:'',email:'',role:'volunteer',brgy:'b1'};title=d.id?'Edit user':'Add user';body=`<label class="field" for="us-n"><span>Full name</span><input id="us-n" value="${esc(u.name)}"></label><label class="field" for="us-e"><span>Email</span><input id="us-e" type="email" value="${esc(u.email)}"></label><div class="grid2"><label class="field" for="us-r"><span>Role</span><select id="us-r">${Object.keys(ROLE).map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${ROLE[r].label}</option>`).join('')}</select></label><label class="field" for="us-b"><span>Barangay</span><select id="us-b"><option value="all" ${u.brgy==='all'?'selected':''}>All (admin only)</option>${DB.brgys.map(b=>`<option value="${b.id}" ${u.brgy===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label></div><div class="err" id="us-err"></div>`;foot=cancel+`<button class="btn btn-primary" onclick="A.saveUser('${d.id||''}')">Save</button>`;break}
 case 'pw':title='Temporary password';body=`<p style="margin:0">Give this one-time password to <b>${esc(userById(d.id).name)}</b> in person. They must change it at first login.</p><div class="ph-card mono" style="font-size:22px;text-align:center;letter-spacing:.08em">${esc(d.pw)}</div>`;foot=`<button class="btn btn-primary" onclick="A.closeModal()">Done</button>`;break;
 case 'revoke':title='Revoke device';body=`<p style="margin:0">Revoke <b>${d.id}</b> (${esc(deviceOf(d.id).name)})? It can no longer sync or open the registry. Data on the phone stays encrypted. Unsynced records on it (${pendingOf(d.id)}) will not upload.</p>`;foot=cancel+`<button class="btn btn-danger" onclick="A.revoke('${d.id}')">Revoke access</button>`;break;
 case 'reset':title='Reset demo data';body=`<p style="margin:0">This restores the original sample registry (1,248 households) and removes everything you added in this browser.</p>`;foot=cancel+`<button class="btn btn-danger" onclick="A.resetData()">Reset</button>`;break;
 case 'dup':{const x=hh(d.match);title='Possible match found';body=`<p style="margin:0"><b>${esc(d.name)}</b>, born ${esc(d.birth)}, is already in household <b class="mono">${x.code}</b>.</p><div class="ph-card"><b>${esc(headOf(x).name)}</b> · ${plural(x.members.length,'member')} · ${badge(x.status)}<div class="sm muted" style="margin-top:4px">${esc(x.location)}</div></div><p class="muted sm" style="margin:0">Link to existing household?</p>`;foot=`<button class="btn" onclick="A.wkSave(true)">No, create new</button><button class="btn btn-primary" onclick="A.wkLink('${x.id}')">Link to existing</button>`;break}
 case 'copy':title=d.title||'Copy';wide=true;body=`<p class="muted sm" style="margin:0">Your browser blocked automatic copy. Select all and copy the text below.</p><textarea readonly style="min-height:260px;font-family:var(--mono);font-size:12px" onclick="this.select()">${esc(d.text)}</textarea>`;foot=`<button class="btn btn-primary" onclick="A.closeModal()">Done</button>`;break;
 }
 return `<div class="overlay" style="z-index:49" onclick="A.closeModal()"></div><div class="modal-wrap" onclick="if(event.target===this)A.closeModal()"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2 class="h2" style="font-size:19px">${title}</h2><button class="icon-btn" aria-label="Close" onclick="A.closeModal()">${icon('x',18)}</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div></div></div>`}
